1	/**
2	 * Modal de recebimento na loja com bip QR.
3	 *
4	 * Operador da loja destino bipa cada caixa que está descarregando.
5	 * Para cada UID:
6	 *   1. RPC bipar_etiqueta(uid, 'entrada', { loja_id }) — atomic state machine
7	 *   2. INSERT movimentacoes (tipo='entrada', etiqueta_qr_uid, lote_id, qty)
8	 *   3. Trigger atualizar_estoque_e_alertas atualiza estoque automaticamente
9	 *
10	 * Lista cumulativa de caixas recebidas, com toast por bip.
11	 */
12	import { useMemo, useState } from "react";
13	import { Dialog, DialogContent, DialogTitle } from "@/shared/ui/dialog";
14	import { Button } from "@/shared/ui/button";
15	import { ScrollArea } from "@/shared/ui/scroll-area";
16	import { Bluetooth, Camera, ScanBarcode, ArrowLeft, Package, MapPin, AlertTriangle, RefreshCw, Boxes } from "lucide-react";
17	import { toast } from "sonner";
18	import { Link } from "react-router-dom";
19	import { cn } from "@/shared/lib/utils";
20	import { supabase } from "@/integrations/supabase/client";
21	import { useEtiquetaScanner, playSuccessSound, playErrorSound, playWarningSound, formatBipError, type ScannedPayload } from "@/shared/hooks/useEtiquetaScanner";
22	import { CameraScannerStatus } from "./CameraScannerStatus";
23	
24	interface RecebidoItem {
25	  uid: string;
26	  produto_master_id: number;
27	  produto_nome: string;
28	  lote_codigo: string | null;
29	  lote_id: string | null;
30	  quantidade: number;
31	  embalagem: string | null;
32	  recebido_at: number;
33	  alertas: string[];
34	  backfilled: boolean;
35	}
36	
37	interface Props {
38	  isOpen: boolean;
39	  onClose: () => void;
40	  lojaDestinoId: number;
41	  lojaDestinoNome: string;
42	}
43	
44	export function EntradaBipModal({ isOpen, onClose, lojaDestinoId, lojaDestinoNome }: Props) {
45	  const [recebidos, setRecebidos] = useState<RecebidoItem[]>([]);
46	
47	  const handleBip = async (payload: ScannedPayload) => {
48	    if (!payload.uid) {
49	      playErrorSound();
50	      toast.error("Etiqueta sem UID — não rastreável");
51	      return;
52	    }
53	
54	    // Dedupe local (evita re-bipar a mesma caixa antes do banco refletir)
55	    if (recebidos.some((r) => r.uid === payload.uid)) {
56	      playErrorSound();
57	      toast.error("Caixa já recebida nesta sessão");
58	      return;
59	    }
60	
61	    // 1. RPC — valida transição + atualiza loja_atual_id
62	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
63	    const { data: rpc, error: rpcErr } = await (supabase.rpc as any)("bipar_etiqueta", {
64	      p_uid: payload.uid,
65	      p_etapa: "entrada",
66	      p_contexto: {
67	        loja_id: lojaDestinoId,
68	        referencia_tipo: "recebimento",
69	        payload,
70	      },
71	    });
72	    if (rpcErr) {
73	      playErrorSound();
74	      toast.error(`Falha no bip: ${rpcErr.message}`);
75	      return;
76	    }
77	    const result = rpc as {
78	      ok: boolean;
79	      erro?: string;
80	      etiqueta?: {
81	        produto_master_id: number;
82	        produto_nome_snapshot: string | null;
83	        lote_id: string | null;
84	        lote_codigo_snapshot: string | null;
85	        quantidade_interna: number;
86	        embalagem_nome?: string | null;
87	      };
88	      alertas?: string[];
89	      backfilled?: boolean;
90	    };
91	    if (!result?.ok || !result.etiqueta) {
92	      playErrorSound();
93	      toast.error(formatBipError(result?.erro, "entrada"));
94	      if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
95	      return;
96	    }
97	
98	    const et = result.etiqueta;
99	    const qty = Number(et.quantidade_interna || 1);
100	
101	    // 2. INSERT movimentacao tipo=entrada — trigger cuida do saldo
102	    const { data: estoqueAtual } = await supabase
103	      .from("estoque")
104	      .select("quantidade_atual")
105	      .eq("produto_master_id", et.produto_master_id)
106	      .eq("loja_id", lojaDestinoId)
107	      .maybeSingle();
108	
109	    const anterior = (estoqueAtual as { quantidade_atual?: number } | null)?.quantidade_atual ?? 0;
110	    const nova = anterior + qty;
111	
112	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
113	    const { error: movErr } = await (supabase.from("movimentacoes") as any).insert({
114	      produto_master_id: et.produto_master_id,
115	      tipo_movimentacao: "entrada",
116	      quantidade: qty,
117	      quantidade_anterior: anterior,
118	      quantidade_nova: nova,
119	      motivo: "recebimento",
120	      observacoes: `Recebimento por bip — UID ${payload.uid}`,
121	      data_movimentacao: new Date().toISOString(),
122	      loja_id: lojaDestinoId,
123	      lote_id: et.lote_id,
124	      etiqueta_qr_uid: payload.uid,
125	    });
126	
127	    if (movErr) {
128	      playErrorSound();
129	      toast.error(`Erro ao registrar entrada: ${movErr.message}`);
130	      return;
131	    }
132	
133	    playSuccessSound();
134	    if (navigator.vibrate) navigator.vibrate(100);
135	    toast.success(`Recebido: ${et.produto_nome_snapshot || `#${et.produto_master_id}`} (${qty} un)`);
136	    (result.alertas ?? []).forEach((a) => {
137	      playWarningSound();
138	      toast.warning(a);
139	    });
140	
141	    setRecebidos((prev) => [
142	      {
143	        uid: payload.uid,
144	        produto_master_id: et.produto_master_id,
145	        produto_nome: et.produto_nome_snapshot || `Produto #${et.produto_master_id}`,
146	        lote_codigo: et.lote_codigo_snapshot,
147	        lote_id: et.lote_id,
148	        quantidade: qty,
149	        embalagem: et.embalagem_nome ?? null,
150	        recebido_at: Date.now(),
151	        alertas: result.alertas ?? [],
152	        backfilled: !!result.backfilled,
153	      },
154	      ...prev,
155	    ]);
156	  };
157	
158	  const scanner = useEtiquetaScanner({
159	    enabled: isOpen,
160	    onScan: handleBip,
161	    cameraElementId: "entrada-qr-reader",
162	    onInvalid: () => toast.error("QR ilegível"),
163	    onDuplicate: () => {
164	      playErrorSound();
165	      toast.error("Esta etiqueta já foi bipada");
166	      if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
167	    },
168	  });
169	
170	  const stats = useMemo(() => {
171	    const totalCaixas = recebidos.length;
172	    const totalUn = recebidos.reduce((acc, r) => acc + r.quantidade, 0);
173	    const produtosUnicos = new Set(recebidos.map((r) => r.produto_master_id)).size;
174	    return { totalCaixas, totalUn, produtosUnicos };
175	  }, [recebidos]);
176	
177	  // Agregação por produto: caixas + un totais por produto_master_id
178	  const porProduto = useMemo(() => {
179	    const map = new Map<number, { nome: string; embalagem: string | null; caixas: number; un: number }>();
180	    for (const r of recebidos) {
181	      const cur = map.get(r.produto_master_id) ?? { nome: r.produto_nome, embalagem: r.embalagem, caixas: 0, un: 0 };
182	      cur.caixas += 1;
183	      cur.un += r.quantidade;
184	      map.set(r.produto_master_id, cur);
185	    }
186	    return Array.from(map.entries())
187	      .map(([pid, v]) => ({ pid, ...v }))
188	      .sort((a, b) => b.un - a.un);
189	  }, [recebidos]);
190	
191	  return (
192	    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
193	      <DialogContent data-mia-modal="recebimento-por-bip" className="max-w-[100vw] sm:max-w-[98vw] w-full h-[100dvh] sm:h-[95vh] p-0 flex flex-col overflow-hidden bg-background sm:rounded-[1.5rem] rounded-none">
194	        {/* Header */}
195	        <div className="flex items-center justify-between gap-2 px-3 sm:px-5 py-2 sm:py-3 flex-shrink-0 border-b border-border/50">
196	          <div className="flex items-center gap-2 sm:gap-3 min-w-0 flex-1">
197	            <Button data-mia-action="on-close" variant="ghost" size="icon" onClick={onClose} className="rounded-2xl hover:bg-[#57715B]/10 h-11 w-11 flex-shrink-0">
198	              <ArrowLeft className="w-5 h-5 text-[#57715B]" />
199	            </Button>
200	            <div className="h-10 w-10 rounded-2xl bg-[#57715B]/10 flex items-center justify-center flex-shrink-0">
201	              <ScanBarcode className="h-5 w-5 text-[#57715B]" />
202	            </div>
203	            <div className="min-w-0 flex-1">
204	              <DialogTitle className="text-base sm:text-lg font-bold text-[#57715B] dark:text-[#E6DCCF] truncate">Recebimento por bip</DialogTitle>
205	              <p className="text-[11px] sm:text-xs text-muted-foreground flex items-center gap-1 truncate">
206	                <MapPin className="w-3 h-3 flex-shrink-0" /> <span className="truncate">{lojaDestinoNome}</span>
207	              </p>
208	            </div>
209	          </div>
210	          <div className="flex p-1 rounded-xl bg-muted/50 dark:bg-zinc-800 flex-shrink-0">
211	            <button
212	              onClick={() => scanner.setScanMode("bluetooth")}
213	              aria-label="Scanner Bluetooth"
214	              className={cn(
215	                "min-h-[44px] min-w-[44px] px-3 sm:px-4 py-2 text-sm font-medium rounded-lg flex items-center gap-2 transition-all",
216	                scanner.scanMode === "bluetooth" ? "bg-white dark:bg-zinc-700 text-[#57715B] shadow-sm" : "text-muted-foreground hover:text-foreground"
217	              )}
218	            >
219	              <Bluetooth className="h-4 w-4" /> <span className="hidden sm:inline">Scanner</span>
220	            </button>
221	            <button
222	              onClick={() => scanner.setScanMode("camera")}
223	              aria-label="Scanner por câmera"
224	              className={cn(
225	                "min-h-[44px] min-w-[44px] px-3 sm:px-4 py-2 text-sm font-medium rounded-lg flex items-center gap-2 transition-all",
226	                scanner.scanMode === "camera" ? "bg-white dark:bg-zinc-700 text-[#57715B] shadow-sm" : "text-muted-foreground hover:text-foreground"
227	              )}
228	            >
229	              <Camera className="h-4 w-4" /> <span className="hidden sm:inline">Câmera</span>
230	            </button>
231	          </div>
232	        </div>
233	
234	        {/* Stats */}
235	        <div className="px-3 sm:px-5 py-3 flex-shrink-0 border-b border-border/50 grid grid-cols-3 gap-2 sm:gap-3">
236	          <Stat label="Caixas" value={stats.totalCaixas} icon={<Boxes className="w-3 h-3" />} />
237	          <Stat label="Unidades" value={stats.totalUn} />
238	          <Stat label="Produtos" value={stats.produtosUnicos} />
239	        </div>
240	
241	        {/* Scanner input invisível */}
242	        {scanner.scanMode === "bluetooth" && <input {...scanner.inputProps} />}
243	
244	        {/* Body */}
245	        <div className="flex-1 flex flex-col md:flex-row overflow-hidden">
246	          {scanner.scanMode === "camera" ? (
247	            <div className="w-full md:w-[260px] flex-shrink-0 border-b md:border-b-0 md:border-r border-border/50 bg-black overflow-hidden relative">
248	              <div id={scanner.cameraElementId} className="w-full h-[200px] md:h-full" />
249	              <CameraScannerStatus
250	                starting={scanner.cameraStarting}
251	                error={scanner.cameraError}
252	                onRetry={scanner.retryCamera}
253	              />
254	            </div>
255	          ) : (
256	            <div
257	              className="w-full md:w-[200px] flex-shrink-0 border-b md:border-b-0 md:border-r border-border/50 flex flex-col items-center justify-center p-5 cursor-pointer"
258	              onClick={() => document.querySelector<HTMLInputElement>("input[autofocus]")?.focus()}
259	            >
260	              <div className="w-20 h-20 rounded-full bg-[#57715B]/10 flex items-center justify-center relative">
261	                <Bluetooth className="w-9 h-9 text-[#57715B]" />
262	                <div className="absolute inset-0 rounded-full border-[3px] border-[#57715B]/20 border-t-[#57715B] animate-spin" style={{ animationDuration: "3s" }} />
263	              </div>
264	              <h3 className="text-sm font-bold text-[#57715B] dark:text-[#E6DCCF] mt-4">Escaneando...</h3>
265	              <p className="text-[11px] text-muted-foreground text-center mt-1">Aponte para cada caixa que chega</p>
266	            </div>
267	          )}
268	
269	          {/* Lista cumulativa */}
270	          <div className="flex-1 flex flex-col overflow-hidden p-2">
271	            <ScrollArea className="flex-1">
272	              <div className="p-2.5 space-y-3">
273	                {/* Agregação por produto */}
274	                {porProduto.length > 0 && (
275	                  <div className="space-y-1.5">
276	                    <p className="text-[10px] uppercase tracking-widest text-muted-foreground font-bold px-1">
277	                      Total por produto
278	                    </p>
279	                    {porProduto.map((p) => (
280	                      <div key={p.pid} className="rounded-xl border-2 border-emerald-500/30 bg-emerald-500/5 p-2.5 flex items-center justify-between gap-2">
281	                        <p className="text-sm font-semibold leading-tight truncate flex-1 min-w-0">{p.nome}</p>
282	                        <div className="flex items-center gap-2 text-[11px] text-emerald-700 font-bold flex-shrink-0">
283	                          <span className="inline-flex items-center gap-0.5"><Boxes className="w-3 h-3" />{p.caixas}</span>
284	                          <span className="text-muted-foreground">·</span>
285	                          <span>{p.un} un</span>
286	                        </div>
287	                      </div>
288	                    ))}
289	                  </div>
290	                )}
291	
292	                {/* Cards individuais */}
293	                <div className="space-y-2 pt-2 border-t border-border/30">
294	                  <p className="text-[10px] uppercase tracking-widest text-muted-foreground font-bold px-1">
295	                    Caixas recebidas ({recebidos.length})
296	                  </p>
297	                  {recebidos.length === 0 ? (
298	                    <div className="flex flex-col items-center justify-center py-10 text-muted-foreground/40">
299	                      <Package className="w-12 h-12 mb-2" />
300	                      <p className="text-sm font-semibold">Nenhuma caixa recebida ainda</p>
301	                      <p className="text-[11px] mt-1">Bipa a primeira caixa pra começar</p>
302	                    </div>
303	                  ) : (
304	                    recebidos.map((r) => <RecebidoCard key={r.uid} item={r} />)
305	                  )}
306	                </div>
307	              </div>
308	            </ScrollArea>
309	          </div>
310	        </div>
311	
312	        {/* Footer */}
313	        <div
314	          className="px-3 sm:px-5 py-3 border-t border-border/50 flex items-center justify-between gap-2 flex-shrink-0"
315	          style={{ paddingBottom: "calc(env(safe-area-inset-bottom) + 12px)" }}
316	        >
317	          <p className="text-[11px] sm:text-xs text-muted-foreground truncate">
318	            {recebidos.length === 0 ? "Aguardando primeira caixa…" : `${stats.totalCaixas} caixa(s) confirmada(s).`}
319	          </p>
320	          <Button data-mia-action="on-close" onClick={onClose} className="h-11 flex-shrink-0">Encerrar</Button>
321	        </div>
322	      </DialogContent>
323	    </Dialog>
324	  );
325	}
326	
327	function Stat({ label, value, icon }: { label: string; value: number; icon?: React.ReactNode }) {
328	  return (
329	    <div className="text-center min-w-0">
330	      <p className="text-[9px] sm:text-[10px] uppercase tracking-widest text-muted-foreground font-bold truncate flex items-center gap-1 justify-center">
331	        {icon}{label}
332	      </p>
333	      <p className="text-xl sm:text-2xl font-black tabular-nums text-[#57715B]">{value}</p>
334	    </div>
335	  );
336	}
337	
338	function RecebidoCard({ item }: { item: RecebidoItem }) {
339	  return (
340	    <Link
341	      to={`/etiquetas/${item.uid}`}
342	      className="block rounded-2xl bg-white dark:bg-zinc-900 border border-emerald-500/30 p-3 hover:border-emerald-500/60 transition-colors"
343	    >
344	      <div className="flex items-start gap-3">
345	        <div className="h-9 w-9 rounded-xl bg-emerald-500/10 flex items-center justify-center flex-shrink-0">
346	          <Package className="h-4 w-4 text-emerald-600" />
347	        </div>
348	        <div className="flex-1 min-w-0">
349	          <p className="text-sm font-semibold leading-tight truncate">{item.produto_nome}</p>
350	          <div className="flex items-center gap-3 text-[10px] text-muted-foreground mt-1">
351	            {item.lote_codigo && <span>Lote {item.lote_codigo}</span>}
352	            <span className="font-bold text-emerald-700">+1 {item.embalagem || "caixa"} ({item.quantidade} un)</span>
353	            <span className="font-mono truncate">{item.uid}</span>
354	          </div>
355	          {item.backfilled && (
356	            <span className="inline-flex items-center gap-1 text-[10px] text-amber-600 mt-1">
357	              <RefreshCw className="w-3 h-3" /> backfill
358	            </span>
359	          )}
360	          {item.alertas.length > 0 && (
361	            <div className="mt-1 space-y-0.5">
362	              {item.alertas.map((a, i) => (
363	                <span key={i} className="inline-flex items-center gap-1 text-[10px] text-amber-700">
364	                  <AlertTriangle className="w-3 h-3" /> {a}
365	                </span>
366	              ))}
367	            </div>
368	          )}
369	        </div>
370	      </div>
371	    </Link>
372	  );
373	}
