76	// ── Audio (same as Scanner.tsx) ───────────────────────────────────────────
77	
78	const playSuccessSound = () => {
79	    try {
80	        const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
81	        const osc = ctx.createOscillator();
