88	const playErrorSound = () => {
89	    try {
90	        const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
91	        const osc = ctx.createOscillator();
92	        const gain = ctx.createGain();
93	        osc.connect(gain); gain.connect(ctx.destination);
94	        osc.frequency.setValueAtTime(300, ctx.currentTime);
95	        osc.frequency.exponentialRampToValueAtTime(100, ctx.currentTime + 0.3);
96	        osc.type = "square"; gain.gain.value = 0.1;
97	        osc.start(); osc.stop(ctx.currentTime + 0.3);
98	    } catch {}
99	};
100	const playWarningSound = () => {
101	    try {
102	        const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
103	        const osc = ctx.createOscillator();
104	        const gain = ctx.createGain();
105	        osc.connect(gain); gain.connect(ctx.destination);
106	        osc.frequency.value = 500; osc.type = "triangle"; gain.gain.value = 0.1;
107	        osc.start(); osc.stop(ctx.currentTime + 0.25);
108	    } catch {}
109	};
110	
111	// ── Hex decoder (same as Scanner.tsx) ─────────────────────────────────────
112	
113	const decodeHex = (hex: string) => {
114	    const bytes = new Uint8Array(hex.length / 2);
115	    for (let i = 0; i < hex.length; i += 2) bytes[i / 2] = parseInt(hex.substring(i, i + 2), 16);
116	    return new TextDecoder().decode(bytes);
117	};
118	
119	// ── Name matching (world-class robustness) ───────────────────────────────
120	
121	function normalizeStr(s: string) {
122	    return s.toLowerCase()
123	        .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
124	        .replace(/[^a-z0-9]/g, "")
125	        .trim();
126	}
127	
128	// Tokenize: removes accents AND punctuation from each token
129	function tokenize(s: string): string[] {
130	    return s.toLowerCase()
131	        .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
132	        .replace(/[^a-z0-9\s]/g, " ")   // punctuation → space (not glued together)
133	        .split(/\s+/)
134	        .filter(w => w.length > 1);
135	}
136	
137	// Levenshtein distance (space-optimised, O(n) space)
138	function editDistance(a: string, b: string): number {
139	    if (a === b) return 0;
140	    if (a.length === 0) return b.length;
141	    if (b.length === 0) return a.length;
142	    const dp: number[] = Array.from({ length: b.length + 1 }, (_, i) => i);
143	    for (let i = 1; i <= a.length; i++) {
144	        let prev = dp[0];
145	        dp[0] = i;
146	        for (let j = 1; j <= b.length; j++) {
147	            const temp = dp[j];
148	            dp[j] = a[i - 1] === b[j - 1] ? prev : 1 + Math.min(prev, dp[j], dp[j - 1]);
149	            prev = temp;
150	        }
151	    }
152	    return dp[b.length];
153	}
154	
155	// Two tokens are considered the same if: exact | substring | close edit-distance
156	function tokensMatch(a: string, b: string): boolean {
157	    if (a === b) return true;
158	    if (a.includes(b) || b.includes(a)) return true;
159	    const maxLen = Math.max(a.length, b.length);
160	    // Allow 1 edit per 5 chars (handles "pote"/"pot", "banoffee"/"banofee", etc.)
161	    const threshold = Math.max(1, Math.floor(maxLen / 5));
162	    return maxLen >= 4 && editDistance(a, b) <= threshold;
163	}
164	
165	// Returns a 0–1 similarity score between two product names
166	function productNameScore(a: string, b: string): number {
167	    const na = normalizeStr(a), nb = normalizeStr(b);
168	    if (!na || !nb) return 0;
169	    if (na === nb) return 1;
170	    if (na.length > 4 && nb.length > 4 && (na.includes(nb) || nb.includes(na))) return 0.95;
171	
172	    const wa = tokenize(a), wb = tokenize(b);
173	    if (wa.length === 0 || wb.length === 0) return 0;
174	
175	    // Single-token case
176	    if (wa.length === 1 && wb.length === 1) return tokensMatch(wa[0], wb[0]) ? 0.85 : 0;
177	
178	    if (wa.length >= 2 && wb.length >= 2) {
179	        const aMatchedInB = wa.filter(w => wb.some(x => tokensMatch(x, w))).length;
180	        const bMatchedInA = wb.filter(w => wa.some(x => tokensMatch(x, w))).length;
181	        const coverA = aMatchedInB / wa.length;
182	        const coverB = bMatchedInA / wb.length;
183	        // Both must cover at least 80% for safety
184	        if (coverA >= 0.8 || coverB >= 0.8) return Math.max(coverA, coverB);
185	    }
186	    return 0;
187	}
188	
189	const MATCH_THRESHOLD = 0.8;
190	
191	function productNamesMatch(a: string, b: string): boolean {
192	    return productNameScore(a, b) >= MATCH_THRESHOLD;
193	}
194	
195	// Best-match resolver: returns the master product with highest score above threshold
196	function bestProductMatch(
197	    itemName: string,
198	    products: Array<{ id: number; nome: string }>
199	): { id: number; nome: string } | null {
200	    let best: { id: number; nome: string } | null = null;
201	    let bestScore = MATCH_THRESHOLD - 0.001;
202	    for (const p of products) {
203	        const score = productNameScore(p.nome, itemName);
204	        if (score > bestScore) { bestScore = score; best = p; }
205	    }
206	    return best;
207	}
208	
209	// ── Persistence helpers ──────────────────────────────────────────────────
210	const getStorageKey = (reqId: number) => `conferencia-bip-${reqId}`;
211	
212	interface SavedConferenceState {
213	    boxes: BoxCard[];
214	    scannedUids: string[];
215	    savedAt: number;
216	}
217	
218	// Bulk = 1 etiqueta cobre a quantidade total do pedido.
219	// Inclui peso/volume contínuo (kg/g/l/ml) E containers de volume fixo
220	// (balde, galão, tambor, barril, garrafa) — onde o pedido é "1 balde"
221	// = 1 etiqueta com quantidade_interna no rótulo.
222	const BULK_UNITS = new Set([
223	    'kg', 'g', 'l', 'litro', 'litros', 'ml', 'liter', 'liters',
224	    'balde', 'baldes', 'galao', 'galão', 'galões', 'galoes',
225	    'tambor', 'tambores', 'barril', 'barris', 'garrafa', 'garrafas'
226	]);
227	
228	function isBulkMeasure(unit: string | null | undefined): boolean {
229	    return BULK_UNITS.has((unit || '').toLowerCase().trim());
230	}
231	
232	function createBoxesFromItems(items: RequisicaoItem[]): BoxCard[] {
233	    const b: BoxCard[] = [];
234	    items.forEach((item) => {
235	        const unit = item.unidade_medida || 'cx';
236	        if (isBulkMeasure(unit)) {
237	            // Bulk: 1 card para o item inteiro (ex: "10 kg de adoçante" → 1 bip)
238	            const bulkQty = Number(item.quantidade_solicitada) || 1;
239	            b.push({
240	                cardId: `req-${item.id || item.ordem}-bulk`,
241	                itemId: item.id, produtoMasterId: item.produto_id || null,
242	                productName: item.nome_produto,
243	                boxNumber: 1, totalBoxes: 1, category: item.category, status: "pending",
244	                isBulkUnit: true, unidadeMedida: unit, bulkQty,
245	            });
246	        } else {
247	            // Box: 1 card por caixa/unidade (comportamento original)
248	            const qty = Math.max(1, Math.round(Number(item.quantidade_solicitada) || 1));
249	            for (let i = 1; i <= qty; i++) {
250	                b.push({
251	                    cardId: `req-${item.id || item.ordem}-box-${i}`,
252	                    itemId: item.id, produtoMasterId: item.produto_id || null,
253	                    productName: item.nome_produto,
254	                    boxNumber: i, totalBoxes: qty, category: item.category, status: "pending",
255	                });
256	            }
257	        }
258	    });
259	    return b;
260	}
