262	// ══════════════════════════════════════════════════════════════════════════
263	// Main Component
264	// ══════════════════════════════════════════════════════════════════════════
265	
266	export function RequisicaoConferenciaModal({ isOpen, onClose, requisicaoId, requisicaoNome, items, lojaPreparadoraId }: Props) {
267	    // PC = Bluetooth/USB scanner. Mobile/tablet = Câmera (Chrome Android tem
268	    // bug WontFix de keydown que perde chars). Detecta via UA.
269	    const [scanMode, setScanMode] = useState<"bluetooth" | "camera">(
270	        typeof navigator !== "undefined" && /Android|iPad|iPhone|Mobile|Tablet/i.test(navigator.userAgent)
271	            ? "camera"
272	            : "bluetooth"
273	    );
274	    const [scanBuffer, setScanBuffer] = useState("");
275	    const [boxes, setBoxes] = useState<BoxCard[]>([]);
276	    const [scannedUids, setScannedUids] = useState<Set<string>>(new Set());
277	    const [exitLoading, setExitLoading] = useState(false);
278	    const inputRef = useRef<HTMLInputElement>(null);
279	    const html5QrCodeRef = useRef<Html5Qrcode | null>(null);
280	    const [cameraActive, setCameraActive] = useState(false);
281	    // Dialog de "transferir conferencia" — abre quando o operador bipa etiqueta
282	    // que ja foi conferida em OUTRA requisicao. Operador decide se transfere.
283	    const [reconferirDialog, setReconferirDialog] = useState<{
284	        open: boolean;
285	        uid: string;
286	        produto: string;
287	        conferida_at: string | null;
288	        data: ScannedData | null;
289	    }>({ open: false, uid: "", produto: "", conferida_at: null, data: null });
290	
291	    // Init boxes — resolve missing produto_ids + restore saved conference
292	    useEffect(() => {
293	        if (!isOpen || items.length === 0) return;
294	        let cancelled = false;
295	
296	        const init = async () => {
297	            // Fetch ALL products once — resolve IDs AND normalise names to master for every item
298	            let resolvedItems = items;
299	            try {
300	                const { data: products } = await supabase.from("produtos_master").select("id, nome, unidade_medida");
301	                if (products && !cancelled) {
302	                    const masterById = new Map(products.map(p => [p.id, p.nome as string]));
303	                    // eslint-disable-next-line @typescript-eslint/no-explicit-any
304	                    const masterUnitById = new Map(products.map(p => [p.id, (p as any).unidade_medida as string | null]));
305	                    resolvedItems = items.map(item => {
306	                        // Source of truth = requisicao_itens.unidade_medida.
307	                        // produto_master é fallback quando a requisicao nao tem (legacy).
308	                        const itemUnit = item.unidade_medida && String(item.unidade_medida).trim()
309	                            ? String(item.unidade_medida).trim()
310	                            : null;
311	                        if (item.produto_id) {
312	                            const masterName = masterById.get(item.produto_id);
313	                            const masterUnit = masterUnitById.get(item.produto_id);
314	                            return {
315	                                ...item,
316	                                ...(masterName ? { nome_produto: masterName } : {}),
317	                                unidade_medida: itemUnit || masterUnit || 'cx',
318	                            };
319	                        }
320	                        const match = bestProductMatch(item.nome_produto, products as { id: number; nome: string }[]);
321	                        if (match) {
322	                            const masterUnit = masterUnitById.get(match.id);
323	                            return {
324	                                ...item,
325	                                produto_id: match.id,
326	                                nome_produto: match.nome,
327	                                unidade_medida: itemUnit || masterUnit || 'cx',
328	                            };
329	                        }
330	                        return { ...item, unidade_medida: itemUnit || 'cx' };
331	                    });
332	                }
333	            } catch { /* fallback: use items as-is */ }
334	            if (cancelled) return;
335	
336	            const freshBoxes = createBoxesFromItems(resolvedItems);
337	
338	            // Try to restore saved conference state
339	            const saved = localStorage.getItem(getStorageKey(requisicaoId));
340	            if (saved) {
341	                try {
342	                    const state: SavedConferenceState = JSON.parse(saved);
343	                    const savedMap = new Map(state.boxes.map(b => [b.cardId, b]));
344	                    const restoredBoxes = freshBoxes.map(box => {
345	                        const s = savedMap.get(box.cardId);
346	                        if (s && s.status === "confirmed") {
347	                            return { ...box, status: "confirmed" as const, scannedData: s.scannedData, scannedProductName: s.scannedProductName, scannedAt: s.scannedAt };
348	                        }
349	                        return box;
350	                    });
351	                    const extras = state.boxes.filter(b => b.status === "extra");
352	                    setBoxes([...restoredBoxes, ...extras]);
353	                    setScannedUids(new Set(state.scannedUids));
354	                    return;
355	                } catch {}
356	            }
357	
358	            setBoxes(freshBoxes);
359	            setScannedUids(new Set());
360	        };
361	
362	        init();
363	        return () => { cancelled = true; };
364	    }, [isOpen, items, requisicaoId]);
365	
366	    // Persist conference state to localStorage on every change
367	    useEffect(() => {
368	        if (boxes.length === 0) return;
369	        const hasProgress = boxes.some(b => b.status !== "pending");
370	        if (!hasProgress) {
371	            localStorage.removeItem(getStorageKey(requisicaoId));
372	            return;
373	        }
374	        const state: SavedConferenceState = { boxes, scannedUids: Array.from(scannedUids), savedAt: Date.now() };
375	        localStorage.setItem(getStorageKey(requisicaoId), JSON.stringify(state));
376	    }, [boxes, scannedUids, requisicaoId]);
377	
378	    // External scanner focus (same as Scanner.tsx)
379	    useEffect(() => {
380	        if (!isOpen || scanMode !== "bluetooth") return;
381	        inputRef.current?.focus();
382	        const iv = setInterval(() => {
383	            if (document.activeElement !== inputRef.current && scanMode === "bluetooth") inputRef.current?.focus();
384	        }, 500);
385	        return () => clearInterval(iv);
386	    }, [isOpen, scanMode]);
387	
388	    // Camera com fallback de facingMode + CSS forçando alinhamento (mesmo
389	    // pattern de useEtiquetaScanner). Em alguns tablets Android, video
390	    // estoura container sem object-fit: cover.
391	    useEffect(() => {
392	        if (!isOpen || scanMode !== "camera") return;
393	        let cancelled = false;
394	
395	        // CSS injetado uma vez pra video preencher container redondinho.
396	        const STYLE_ID = "conferencia-camera-css";
397	        if (typeof document !== "undefined" && !document.getElementById(STYLE_ID)) {
398	            const styleEl = document.createElement("style");
399	            styleEl.id = STYLE_ID;
400	            styleEl.textContent = `
401	              [data-html5-qrcode-region="true"] {
402	                position: relative !important;
403	                width: 100% !important;
404	                height: 100% !important;
405	                overflow: hidden !important;
406	                background: black !important;
407	              }
408	              [data-html5-qrcode-region="true"] video {
409	                width: 100% !important;
410	                height: 100% !important;
411	                object-fit: cover !important;
412	                display: block !important;
413	              }
414	              [data-html5-qrcode-region="true"] img {
415	                display: none !important;
416	              }
417	            `;
418	            document.head.appendChild(styleEl);
419	        }
420	
421	        const start = async () => {
422	            // Espera pelo elemento com retry (race entre useEffect e mount do <div>)
423	            let el: HTMLElement | null = null;
424	            for (let i = 0; i < 10; i++) {
425	                if (cancelled) return;
426	                el = document.getElementById("conferencia-qr-reader");
427	                if (el) break;
428	                await new Promise((r) => setTimeout(r, 50));
429	            }
430	            if (!el || cancelled) {
431	                if (!cancelled) toast.error("Não foi possível inicializar o leitor");
432	                return;
433	            }
434	            el.setAttribute("data-html5-qrcode-region", "true");
435	
436	            const qr = new Html5Qrcode("conferencia-qr-reader");
437	            html5QrCodeRef.current = qr;
438	            const cameraConfig = {
439	                fps: 10,
440	                qrbox: (vw: number, vh: number) => {
441	                    const minEdge = Math.min(vw, vh);
442	                    const size = Math.max(140, Math.floor(minEdge * 0.7));
443	                    return { width: size, height: size };
444	                },
445	            };
446	
447	            // Estratégia 1: facingMode environment
448	            try {
449	                await qr.start({ facingMode: "environment" }, cameraConfig, (t) => handleScan(t), () => { /* frame fail */ });
450	                if (cancelled) { await qr.stop().catch(() => undefined); return; }
451	                setCameraActive(true);
452	                return;
453	            } catch (err1) {
454	                // Estratégia 2: lista câmeras e usa traseira ou primeira
455	                try {
456	                    const cams = await Html5Qrcode.getCameras();
457	                    if (cancelled) return;
458	                    if (!cams || cams.length === 0) {
459	                        toast.error("Nenhuma câmera detectada neste aparelho");
460	                        return;
461	                    }
462	                    const back = cams.find((c) => /back|rear|environment|traseira/i.test(c.label || ""));
463	                    const deviceId = (back ?? cams[0]).id;
464	                    await qr.start(deviceId, cameraConfig, (t) => handleScan(t), () => { /* frame fail */ });
465	                    if (cancelled) { await qr.stop().catch(() => undefined); return; }
466	                    setCameraActive(true);
467	                } catch (err2) {
468	                    if (cancelled) return;
469	                    handleError(err2 ?? err1, { domain: 'logistica', operation: 'startCamera', showToast: false });
470	                    const e = err2 as { name?: string; message?: string };
471	                    if (e?.name === "NotAllowedError") toast.error("Permissão da câmera negada — libere nas configurações do navegador");
472	                    else if (e?.name === "NotFoundError") toast.error("Nenhuma câmera detectada");
473	                    else if (e?.name === "NotReadableError") toast.error("Câmera ocupada por outro app");
474	                    else toast.error(e?.message || "Erro ao iniciar câmera");
475	                }
476	            }
477	        };
478	
479	        void start();
480	
481	        return () => {
482	            cancelled = true;
483	            if (html5QrCodeRef.current?.isScanning) {
484	                html5QrCodeRef.current.stop().catch((e) => handleError(e, { domain: 'logistica', operation: 'stopCamera', showToast: false }));
485	            }
486	            setCameraActive(false);
487	        };
488	    }, [isOpen, scanMode]);
489	
490	    // Parse QR — sanitiza ruído de scanner Bluetooth (replacement char, controles,
491	    // BOM) antes de tentar cada formato. Em hex degradado, extrai só [0-9a-f] se
492	    // representar a maior parte do conteúdo. Sem isso, scanner em tablet emite
493	    // � que faz JSON.parse explodir.
494	    const parseQrData = useCallback((value: string): ScannedData | null => {
495	        // eslint-disable-next-line no-control-regex
496	        const sanitized = (value || "")
497	            .replace(/[\uFFFD\uFEFF]/g, "")
498	            // eslint-disable-next-line no-control-regex
499	            .replace(/[\x00-\x08\x0B-\x1F\x7F]/g, "")
500	            .trim();
501	        if (!sanitized) return null;
502	
503	        const tryParse = (input: string): { pid: string; lid: string; lote: string; val: string; eid: string; emb: string; qty: number; uid?: string } | null => {
504	            try {
505	                // 0) UID puro — formato canônico atual (QR contém só UID, 4-32 alfanuméricos sem '{')
506	                if (!input.includes("{") && /^[0-9a-zA-Z]{4,32}$/.test(input)) {
507	                    return { pid: "", lid: "", lote: "", val: "", eid: "", emb: "", qty: 1, uid: input };
508	                }
509	                const lower = input.toLowerCase();
