import { cn } from "@/shared/lib/utils";
import { handleError } from '@/shared/lib/error-handler';

// ── Types ──────────────────────────────────────────────────────────────────

interface RequisicaoItem {
    id?: number;
    requisicao_id?: number;
    nome_produto: string;
    quantidade_solicitada: string;
    quantidade_enviada: string;
    observacao: string;
    ordem: number;
    category?: string;
    lote?: string;
    validade?: string;
    produto_id?: number | null;
    unidade_medida?: string | null;
}

interface ScannedData {
    pid: string;
    lid: string;
    lote: string;
    val: string;
    eid: string;
    emb: string;
    qty: number;
    uid?: string;
}

interface BoxCard {
    cardId: string;
    itemId: number | undefined;
    produtoMasterId: number | null;
    productName: string;
    boxNumber: number;
    totalBoxes: number;
    category?: string;
    status: "pending" | "confirmed" | "extra";
    scannedData?: ScannedData;
    scannedProductName?: string;
    scannedAt?: number;
    // Unidade de medida: quando não é "cx/caixa", exibe qtd+unit em vez de "Cx N/M"
    isBulkUnit?: boolean;
    unidadeMedida?: string;
    bulkQty?: number; // quantidade_solicitada para itens bulk (para movimento sem uid)
}

interface Props {
    isOpen: boolean;
    onClose: () => void;
    requisicaoId: number;
    requisicaoNome: string;
    items: RequisicaoItem[];
    lojaPreparadoraId?: number | null;
}

// ── Audio (same as Scanner.tsx) ───────────────────────────────────────────

const playSuccessSound = () => {
    try {
        const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.connect(gain); gain.connect(ctx.destination);
        osc.frequency.value = 800; osc.type = "sine"; gain.gain.value = 0.1;
        osc.start(); osc.stop(ctx.currentTime + 0.15);
    } catch {}
};
const playErrorSound = () => {
    try {
        const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.connect(gain); gain.connect(ctx.destination);
        osc.frequency.setValueAtTime(300, ctx.currentTime);
        osc.frequency.exponentialRampToValueAtTime(100, ctx.currentTime + 0.3);
        osc.type = "square"; gain.gain.value = 0.1;
        osc.start(); osc.stop(ctx.currentTime + 0.3);
    } catch {}
};
const playWarningSound = () => {
    try {
        const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.connect(gain); gain.connect(ctx.destination);
        osc.frequency.value = 500; osc.type = "triangle"; gain.gain.value = 0.1;
        osc.start(); osc.stop(ctx.currentTime + 0.25);
    } catch {}
};

// ── Hex decoder (same as Scanner.tsx) ─────────────────────────────────────

const decodeHex = (hex: string) => {
    const bytes = new Uint8Array(hex.length / 2);
    for (let i = 0; i < hex.length; i += 2) bytes[i / 2] = parseInt(hex.substring(i, i + 2), 16);
    return new TextDecoder().decode(bytes);
};

// ── Name matching (world-class robustness) ───────────────────────────────

function normalizeStr(s: string) {
    return s.toLowerCase()
        .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
        .replace(/[^a-z0-9]/g, "")
        .trim();
}

// Tokenize: removes accents AND punctuation from each token
function tokenize(s: string): string[] {
    return s.toLowerCase()
        .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
        .replace(/[^a-z0-9\s]/g, " ")   // punctuation → space (not glued together)
        .split(/\s+/)
        .filter(w => w.length > 1);
}

// Levenshtein distance (space-optimised, O(n) space)
function editDistance(a: string, b: string): number {
    if (a === b) return 0;
    if (a.length === 0) return b.length;
    if (b.length === 0) return a.length;
    const dp: number[] = Array.from({ length: b.length + 1 }, (_, i) => i);
    for (let i = 1; i <= a.length; i++) {
        let prev = dp[0];
        dp[0] = i;
        for (let j = 1; j <= b.length; j++) {
            const temp = dp[j];
            dp[j] = a[i - 1] === b[j - 1] ? prev : 1 + Math.min(prev, dp[j], dp[j - 1]);
            prev = temp;
        }
    }
    return dp[b.length];
}

// Two tokens are considered the same if: exact | substring | close edit-distance
function tokensMatch(a: string, b: string): boolean {
    if (a === b) return true;
    if (a.includes(b) || b.includes(a)) return true;
    const maxLen = Math.max(a.length, b.length);
    // Allow 1 edit per 5 chars (handles "pote"/"pot", "banoffee"/"banofee", etc.)
    const threshold = Math.max(1, Math.floor(maxLen / 5));
    return maxLen >= 4 && editDistance(a, b) <= threshold;
}

// Returns a 0–1 similarity score between two product names
function productNameScore(a: string, b: string): number {
    const na = normalizeStr(a), nb = normalizeStr(b);
    if (!na || !nb) return 0;
    if (na === nb) return 1;
    if (na.length > 4 && nb.length > 4 && (na.includes(nb) || nb.includes(na))) return 0.95;

    const wa = tokenize(a), wb = tokenize(b);
    if (wa.length === 0 || wb.length === 0) return 0;

    // Single-token case
    if (wa.length === 1 && wb.length === 1) return tokensMatch(wa[0], wb[0]) ? 0.85 : 0;

    if (wa.length >= 2 && wb.length >= 2) {
        const aMatchedInB = wa.filter(w => wb.some(x => tokensMatch(x, w))).length;
        const bMatchedInA = wb.filter(w => wa.some(x => tokensMatch(x, w))).length;
        const coverA = aMatchedInB / wa.length;
        const coverB = bMatchedInA / wb.length;
        // Both must cover at least 80% for safety
        if (coverA >= 0.8 || coverB >= 0.8) return Math.max(coverA, coverB);
    }
    return 0;
}

const MATCH_THRESHOLD = 0.8;

function productNamesMatch(a: string, b: string): boolean {
    return productNameScore(a, b) >= MATCH_THRESHOLD;
}

// Best-match resolver: returns the master product with highest score above threshold
function bestProductMatch(
    itemName: string,
    products: Array<{ id: number; nome: string }>
): { id: number; nome: string } | null {
    let best: { id: number; nome: string } | null = null;
    let bestScore = MATCH_THRESHOLD - 0.001;
    for (const p of products) {
        const score = productNameScore(p.nome, itemName);
        if (score > bestScore) { bestScore = score; best = p; }
    }
    return best;
}

// ── Persistence helpers ──────────────────────────────────────────────────
const getStorageKey = (reqId: number) => `conferencia-bip-${reqId}`;

interface SavedConferenceState {
    boxes: BoxCard[];
    scannedUids: string[];
    savedAt: number;
}

// Bulk = 1 etiqueta cobre a quantidade total do pedido.
// Inclui peso/volume contínuo (kg/g/l/ml) E containers de volume fixo
// (balde, galão, tambor, barril, garrafa) — onde o pedido é "1 balde"
// = 1 etiqueta com quantidade_interna no rótulo.
const BULK_UNITS = new Set([
    'kg', 'g', 'l', 'litro', 'litros', 'ml', 'liter', 'liters',
    'balde', 'baldes', 'galao', 'galão', 'galões', 'galoes',
    'tambor', 'tambores', 'barril', 'barris', 'garrafa', 'garrafas'
]);

function isBulkMeasure(unit: string | null | undefined): boolean {
    return BULK_UNITS.has((unit || '').toLowerCase().trim());
}

function createBoxesFromItems(items: RequisicaoItem[]): BoxCard[] {
    const b: BoxCard[] = [];
    items.forEach((item) => {
        const unit = item.unidade_medida || 'cx';
        if (isBulkMeasure(unit)) {
            // Bulk: 1 card para o item inteiro (ex: "10 kg de adoçante" → 1 bip)
            const bulkQty = Number(item.quantidade_solicitada) || 1;
            b.push({
                cardId: `req-${item.id || item.ordem}-bulk`,
                itemId: item.id, produtoMasterId: item.produto_id || null,
                productName: item.nome_produto,
                boxNumber: 1, totalBoxes: 1, category: item.category, status: "pending",
                isBulkUnit: true, unidadeMedida: unit, bulkQty,
            });
        } else {
            // Box: 1 card por caixa/unidade (comportamento original)
            const qty = Math.max(1, Math.round(Number(item.quantidade_solicitada) || 1));
            for (let i = 1; i <= qty; i++) {
                b.push({
                    cardId: `req-${item.id || item.ordem}-box-${i}`,
                    itemId: item.id, produtoMasterId: item.produto_id || null,
                    productName: item.nome_produto,
                    boxNumber: i, totalBoxes: qty, category: item.category, status: "pending",
                });
            }
        }
    });
    return b;
}

// ══════════════════════════════════════════════════════════════════════════
// Main Component
// ══════════════════════════════════════════════════════════════════════════

export function RequisicaoConferenciaModal({ isOpen, onClose, requisicaoId, requisicaoNome, items, lojaPreparadoraId }: Props) {
    // PC = Bluetooth/USB scanner. Mobile/tablet = Câmera (Chrome Android tem
    // bug WontFix de keydown que perde chars). Detecta via UA.
    const [scanMode, setScanMode] = useState<"bluetooth" | "camera">(
        typeof navigator !== "undefined" && /Android|iPad|iPhone|Mobile|Tablet/i.test(navigator.userAgent)
            ? "camera"
            : "bluetooth"
    );
    const [scanBuffer, setScanBuffer] = useState("");
    const [boxes, setBoxes] = useState<BoxCard[]>([]);
    const [scannedUids, setScannedUids] = useState<Set<string>>(new Set());
    const [exitLoading, setExitLoading] = useState(false);
    const inputRef = useRef<HTMLInputElement>(null);
    const html5QrCodeRef = useRef<Html5Qrcode | null>(null);
    const [cameraActive, setCameraActive] = useState(false);
    // Dialog de "transferir conferencia" — abre quando o operador bipa etiqueta
    // que ja foi conferida em OUTRA requisicao. Operador decide se transfere.
    const [reconferirDialog, setReconferirDialog] = useState<{
        open: boolean;
        uid: string;
        produto: string;
        conferida_at: string | null;
        data: ScannedData | null;
    }>({ open: false, uid: "", produto: "", conferida_at: null, data: null });

    // Init boxes — resolve missing produto_ids + restore saved conference
    useEffect(() => {
        if (!isOpen || items.length === 0) return;
        let cancelled = false;

        const init = async () => {
            // Fetch ALL products once — resolve IDs AND normalise names to master for every item
            let resolvedItems = items;
            try {
                const { data: products } = await supabase.from("produtos_master").select("id, nome, unidade_medida");
                if (products && !cancelled) {
                    const masterById = new Map(products.map(p => [p.id, p.nome as string]));
                    // eslint-disable-next-line @typescript-eslint/no-explicit-any
                    const masterUnitById = new Map(products.map(p => [p.id, (p as any).unidade_medida as string | null]));
                    resolvedItems = items.map(item => {
                        // Source of truth = requisicao_itens.unidade_medida.
                        // produto_master é fallback quando a requisicao nao tem (legacy).
                        const itemUnit = item.unidade_medida && String(item.unidade_medida).trim()
                            ? String(item.unidade_medida).trim()
                            : null;
                        if (item.produto_id) {
                            const masterName = masterById.get(item.produto_id);
                            const masterUnit = masterUnitById.get(item.produto_id);
                            return {
                                ...item,
                                ...(masterName ? { nome_produto: masterName } : {}),
                                unidade_medida: itemUnit || masterUnit || 'cx',
                            };
                        }
                        const match = bestProductMatch(item.nome_produto, products as { id: number; nome: string }[]);
                        if (match) {
                            const masterUnit = masterUnitById.get(match.id);
                            return {
                                ...item,
                                produto_id: match.id,
                                nome_produto: match.nome,
                                unidade_medida: itemUnit || masterUnit || 'cx',
                            };
                        }
                        return { ...item, unidade_medida: itemUnit || 'cx' };
                    });
                }
            } catch { /* fallback: use items as-is */ }
            if (cancelled) return;

            const freshBoxes = createBoxesFromItems(resolvedItems);

            // Try to restore saved conference state
            const saved = localStorage.getItem(getStorageKey(requisicaoId));
            if (saved) {
                try {
                    const state: SavedConferenceState = JSON.parse(saved);
                    const savedMap = new Map(state.boxes.map(b => [b.cardId, b]));
                    const restoredBoxes = freshBoxes.map(box => {
                        const s = savedMap.get(box.cardId);
                        if (s && s.status === "confirmed") {
                            return { ...box, status: "confirmed" as const, scannedData: s.scannedData, scannedProductName: s.scannedProductName, scannedAt: s.scannedAt };
                        }
                        return box;
                    });
                    const extras = state.boxes.filter(b => b.status === "extra");
                    setBoxes([...restoredBoxes, ...extras]);
                    setScannedUids(new Set(state.scannedUids));
                    return;
                } catch {}
            }

            setBoxes(freshBoxes);
            setScannedUids(new Set());
        };

        init();
        return () => { cancelled = true; };
    }, [isOpen, items, requisicaoId]);

    // Persist conference state to localStorage on every change
    useEffect(() => {
        if (boxes.length === 0) return;
        const hasProgress = boxes.some(b => b.status !== "pending");
        if (!hasProgress) {
            localStorage.removeItem(getStorageKey(requisicaoId));
            return;
        }
        const state: SavedConferenceState = { boxes, scannedUids: Array.from(scannedUids), savedAt: Date.now() };
        localStorage.setItem(getStorageKey(requisicaoId), JSON.stringify(state));
    }, [boxes, scannedUids, requisicaoId]);

    // External scanner focus (same as Scanner.tsx)
    useEffect(() => {
        if (!isOpen || scanMode !== "bluetooth") return;
        inputRef.current?.focus();
        const iv = setInterval(() => {
            if (document.activeElement !== inputRef.current && scanMode === "bluetooth") inputRef.current?.focus();
        }, 500);
        return () => clearInterval(iv);
    }, [isOpen, scanMode]);

    // Camera com fallback de facingMode + CSS forçando alinhamento (mesmo
    // pattern de useEtiquetaScanner). Em alguns tablets Android, video
    // estoura container sem object-fit: cover.
    useEffect(() => {
        if (!isOpen || scanMode !== "camera") return;
        let cancelled = false;

        // CSS injetado uma vez pra video preencher container redondinho.
        const STYLE_ID = "conferencia-camera-css";
        if (typeof document !== "undefined" && !document.getElementById(STYLE_ID)) {
            const styleEl = document.createElement("style");
            styleEl.id = STYLE_ID;
            styleEl.textContent = `
              [data-html5-qrcode-region="true"] {
                position: relative !important;
                width: 100% !important;
                height: 100% !important;
                overflow: hidden !important;
                background: black !important;
              }
              [data-html5-qrcode-region="true"] video {
                width: 100% !important;
                height: 100% !important;
                object-fit: cover !important;
                display: block !important;
              }
              [data-html5-qrcode-region="true"] img {
                display: none !important;
              }
            `;
            document.head.appendChild(styleEl);
        }

        const start = async () => {
            // Espera pelo elemento com retry (race entre useEffect e mount do <div>)
            let el: HTMLElement | null = null;
            for (let i = 0; i < 10; i++) {
                if (cancelled) return;
                el = document.getElementById("conferencia-qr-reader");
                if (el) break;
                await new Promise((r) => setTimeout(r, 50));
            }
            if (!el || cancelled) {
                if (!cancelled) toast.error("Não foi possível inicializar o leitor");
                return;
            }
            el.setAttribute("data-html5-qrcode-region", "true");

            const qr = new Html5Qrcode("conferencia-qr-reader");
            html5QrCodeRef.current = qr;
            const cameraConfig = {
                fps: 10,
                qrbox: (vw: number, vh: number) => {
                    const minEdge = Math.min(vw, vh);
                    const size = Math.max(140, Math.floor(minEdge * 0.7));
                    return { width: size, height: size };
                },
            };

            // Estratégia 1: facingMode environment
            try {
                await qr.start({ facingMode: "environment" }, cameraConfig, (t) => handleScan(t), () => { /* frame fail */ });
                if (cancelled) { await qr.stop().catch(() => undefined); return; }
                setCameraActive(true);
                return;
            } catch (err1) {
                // Estratégia 2: lista câmeras e usa traseira ou primeira
                try {
                    const cams = await Html5Qrcode.getCameras();
                    if (cancelled) return;
                    if (!cams || cams.length === 0) {
                        toast.error("Nenhuma câmera detectada neste aparelho");
                        return;
                    }
                    const back = cams.find((c) => /back|rear|environment|traseira/i.test(c.label || ""));
                    const deviceId = (back ?? cams[0]).id;
                    await qr.start(deviceId, cameraConfig, (t) => handleScan(t), () => { /* frame fail */ });
                    if (cancelled) { await qr.stop().catch(() => undefined); return; }
                    setCameraActive(true);
                } catch (err2) {
                    if (cancelled) return;
                    handleError(err2 ?? err1, { domain: 'logistica', operation: 'startCamera', showToast: false });
                    const e = err2 as { name?: string; message?: string };
                    if (e?.name === "NotAllowedError") toast.error("Permissão da câmera negada — libere nas configurações do navegador");
                    else if (e?.name === "NotFoundError") toast.error("Nenhuma câmera detectada");
                    else if (e?.name === "NotReadableError") toast.error("Câmera ocupada por outro app");
                    else toast.error(e?.message || "Erro ao iniciar câmera");
                }
            }
        };

        void start();

        return () => {
            cancelled = true;
            if (html5QrCodeRef.current?.isScanning) {
                html5QrCodeRef.current.stop().catch((e) => handleError(e, { domain: 'logistica', operation: 'stopCamera', showToast: false }));
            }
            setCameraActive(false);
        };
    }, [isOpen, scanMode]);

    // Parse QR — sanitiza ruído de scanner Bluetooth (replacement char, controles,
    // BOM) antes de tentar cada formato. Em hex degradado, extrai só [0-9a-f] se
    // representar a maior parte do conteúdo. Sem isso, scanner em tablet emite
    // � que faz JSON.parse explodir.
    const parseQrData = useCallback((value: string): ScannedData | null => {
        // eslint-disable-next-line no-control-regex
        const sanitized = (value || "")
            .replace(/[\uFFFD\uFEFF]/g, "")
            // eslint-disable-next-line no-control-regex
            .replace(/[\x00-\x08\x0B-\x1F\x7F]/g, "")
            .trim();
        if (!sanitized) return null;

        const tryParse = (input: string): { pid: string; lid: string; lote: string; val: string; eid: string; emb: string; qty: number; uid?: string } | null => {
            try {
                // 0) UID puro — formato canônico atual (QR contém só UID, 4-32 alfanuméricos sem '{')
                if (!input.includes("{") && /^[0-9a-zA-Z]{4,32}$/.test(input)) {
                    return { pid: "", lid: "", lote: "", val: "", eid: "", emb: "", qty: 1, uid: input };
                }
                const lower = input.toLowerCase();
                if (/^[0-9a-f]+$/.test(lower) && lower.length > 20) {
                    const raw = JSON.parse(decodeHex(lower));
                    return { pid: raw.pid||raw.p, lid: raw.lid||raw.l, lote: raw.lote||raw.c, val: raw.val||raw.v, eid: raw.eid||raw.e, emb: raw.emb||raw.n, qty: raw.qty||raw.q, uid: raw.uid||raw.u };
                }
                // Hex com lixo no meio: extrai apenas chars hex
                const hexOnly = lower.replace(/[^0-9a-f]/g, "");
                if (hexOnly.length > 20 && hexOnly.length / lower.length > 0.8 && hexOnly.length % 2 === 0) {
                    try {
                        const raw = JSON.parse(decodeHex(hexOnly));
                        return { pid: raw.pid||raw.p, lid: raw.lid||raw.l, lote: raw.lote||raw.c, val: raw.val||raw.v, eid: raw.eid||raw.e, emb: raw.emb||raw.n, qty: raw.qty||raw.q, uid: raw.uid||raw.u };
                    } catch { /* tenta próximos */ }
                }
                if (input.startsWith("{")) {
                    return JSON.parse(input) as ScannedData;
                }
                let r = input; if (!r.startsWith("{")) r = `{${r}}`;
                r = r.replace(/@/g,'"').replace(/>/g,':').replace(/</g,',').replace(/;/g,'-');
                return JSON.parse(r) as ScannedData;
            } catch {
                return null;
            }
        };

        return tryParse(sanitized);
    }, []);

    // Handle scan — passa pela RPC bipar_etiqueta (etapa=conferencia) pra
    // registrar evento no timeline da etiqueta + validar transição
    // separada→conferida. Mantém matching local por produto_master pra UI.
    const handleScan = useCallback(async (value: string) => {
        setScanBuffer("");
        const data = parseQrData(value);
        if (!data || (!data.pid && !data.uid)) {
            playErrorSound();
            toast.error("QR Code inválido ou ilegível");
            if (navigator.vibrate) navigator.vibrate([200,100,200]);
            // Telemetria: sem isso, "etiqueta nao legivel" some do banco e operador
            // fica cego. raw_preview ajuda a diagnosticar QR torto / scanner ABNT.
            void logScannerEvent({
                evento: 'qr_rejected',
                scan_mode: scanMode,
                raw_len: value?.length ?? 0,
                raw_preview: (value || "").slice(0, 400),
                raw_is_only_hex: /^[0-9a-f]+$/i.test((value || "").trim()),
                raw_is_odd_len: (value?.length ?? 0) % 2 === 1,
                erro_mensagem: 'conferencia: parseQrData falhou',
            });
            return;
        }
        const scanKey = data.uid || value;
        if (scannedUids.has(scanKey)) {
            playErrorSound();
            toast.error("Caixa já bipada!");
            if (navigator.vibrate) navigator.vibrate([200,100,200]);
            void logScannerEvent({
                evento: 'qr_duplicate',
                scan_mode: scanMode,
                scan_uid: data.uid || null,
                scan_pid: data.pid || null,
                raw_len: value?.length ?? 0,
                raw_preview: (value || "").slice(0, 400),
            });
            return;
        }
        // Sucesso: registra qr_scanned (operador pode ver no painel admin)
        void logScannerEvent({
            evento: 'qr_scanned',
            scan_mode: scanMode,
            scan_uid: data.uid || null,
            scan_pid: data.pid || null,
            raw_len: value?.length ?? 0,
            raw_preview: (value || "").slice(0, 400),
        });

        let productName = "";
        let scannedPid = parseInt(data.pid);

        // RPC central: registra evento de conferência + transição de status.
        // Só chama se temos UID — senão segue fluxo legado (etiqueta sem QR estruturado).
        if (data.uid) {
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            const { data: rpcRaw, error: rpcErr } = await (supabase.rpc as any)("bipar_etiqueta", {
                p_uid: data.uid,
                p_etapa: "conferencia",
                p_contexto: {
                    loja_id: lojaPreparadoraId,
                    referencia_tipo: "requisicao",
                    referencia_id: String(requisicaoId),
                    payload: data,
                },
            });
            const rpc = rpcRaw as {
                ok: boolean;
                erro?: string;
                etiqueta?: { produto_master_id: number; produto_nome_snapshot?: string | null; embalagem_nome?: string | null; tipo_embalagem?: string | null; quantidade_interna?: number; conferida_at?: string | null; separada_at?: string | null };
                alertas?: string[];
                backfilled?: boolean;
            } | null;
            if (rpcErr || !rpc?.ok) {
                // Caso especial: ja conferida → abrir dialog pra transferir
                const erroLower = (rpc?.erro || rpcErr?.message || "").toLowerCase();
                const isJaConferida = erroLower.includes('"conferida"') || erroLower.includes("conferida");
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                const etConf = rpc?.etiqueta as any;
                if (isJaConferida && etConf?.conferida_at) {
                    playWarningSound();
                    setReconferirDialog({
                        open: true,
                        uid: data.uid,
                        produto: etConf.produto_nome_snapshot || "produto",
                        conferida_at: etConf.conferida_at,
                        data,
                    });
                    return;
                }
                playErrorSound();
                if (navigator.vibrate) navigator.vibrate([200,100,200]);
                toast.error(formatBipError(rpc?.erro || rpcErr?.message, "conferencia", rpc?.etiqueta));
                if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
                return;
            }
            (rpc.alertas ?? []).forEach((a) => { playWarningSound(); toast.warning(a); });
            if (rpc.etiqueta) {
                scannedPid = rpc.etiqueta.produto_master_id;
                productName = rpc.etiqueta.produto_nome_snapshot || "";
                // Warning cruzado removido — com a nova regra (container = +1 sempre),
                // mismatch de unidade interna da etiqueta vs unidade do pedido eh ruido.
            }
        }

        // Fallback de produto_nome (se RPC não veio com snapshot ou não houve UID)
        if (!productName) {
            try {
                const { data: p } = await supabase.from("produtos_master").select("id, nome").eq("id", scannedPid).single();
                productName = p?.nome || "";
            } catch { /* ignora */ }
        }
        if (!productName) { playErrorSound(); toast.error("Produto não encontrado no sistema"); return; }

        // Tipo + qty da etiqueta (RPC tem prioridade; payload é fallback)
        const tipoEtq = rpc?.etiqueta?.tipo_embalagem ?? data.tipo ?? null;
        const qtyEtq = Number(rpc?.etiqueta?.quantidade_interna ?? data.qty ?? 1);

        setScannedUids(prev => new Set(prev).add(scanKey));
        setBoxes(prev => {
            // Match: primeiro produto_id; fallback fuzzy de nome (itens sem produto_id)
            let firstIdx = prev.findIndex(b => b.status === "pending" && b.produtoMasterId === scannedPid);
            if (firstIdx < 0) firstIdx = prev.findIndex(b => b.status === "pending" && productNamesMatch(b.productName, productName));

            if (firstIdx >= 0) {
                // Regra universal: pedido bate com tipo da etiqueta → 1 card; senão → qty_interna cards
                const cardsCobertos = calcularIncrementoBip(prev[firstIdx].unidadeMedida, tipoEtq, qtyEtq);
                playSuccessSound(); if (navigator.vibrate) navigator.vibrate(100);
                toast.success(cardsCobertos > 1 ? `Conferido: ${productName} (+${cardsCobertos})` : `Conferido: ${productName}`);
                const u = [...prev];
                let marcados = 0;
                for (let i = 0; i < u.length && marcados < cardsCobertos; i++) {
                    const matchByPid = scannedPid && u[i].produtoMasterId === scannedPid;
                    const matchByName = !matchByPid && productNamesMatch(u[i].productName, productName);
                    if (u[i].status === "pending" && (matchByPid || matchByName)) {
                        u[i] = {
                            ...u[i],
                            status: "confirmed",
                            scannedData: marcados === 0 ? data : u[i].scannedData,
                            scannedProductName: productName,
                            scannedAt: Date.now(),
                        };
                        marcados++;
                    }
                }
                return u;
            } else {
                // Item nao esta na lista → registra silenciosamente como "Fora da Lista"
                // (card laranja na 3a coluna). Sem toast — operador ve no painel quando precisar.
                if (navigator.vibrate) navigator.vibrate([50]);
                return [...prev, { cardId: `extra-${Date.now()}-${Math.random().toString(36).substring(7)}`, itemId: undefined, produtoMasterId: null, productName, boxNumber: 1, totalBoxes: 1, status: "extra" as const, scannedData: data, scannedProductName: productName, scannedAt: Date.now() }];
            }
        });
    }, [parseQrData, scannedUids, lojaPreparadoraId, requisicaoId, items, scanMode]);

    // Transfere conferencia da requisicao anterior pra essa — sobrescreve conferida_at/por
    const confirmarReconferir = async () => {
        if (!reconferirDialog.uid || !reconferirDialog.data) {
            setReconferirDialog({ open: false, uid: "", produto: "", conferida_at: null, data: null });
            return;
        }
        const data = reconferirDialog.data;
        try {
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            const { data: rpcRaw, error: rpcErr } = await (supabase.rpc as any)("bipar_etiqueta_reconferir", {
                p_uid: reconferirDialog.uid,
                p_contexto: {
                    loja_id: lojaPreparadoraId,
                    referencia_tipo: "requisicao",
                    referencia_id: String(requisicaoId),
                    payload: data,
                },
            });
            const rpc = rpcRaw as { ok: boolean; erro?: string; etiqueta?: { produto_master_id: number; produto_nome_snapshot?: string | null; tipo_embalagem?: string | null; quantidade_interna?: number } } | null;
            if (rpcErr || !rpc?.ok) {
                toast.error(rpc?.erro || rpcErr?.message || "Falha ao transferir conferência");
                playErrorSound();
                return;
            }
            // Aplica visualmente o bip — copia logica do handleScan apos sucesso da RPC
            const scannedPid = rpc.etiqueta?.produto_master_id ?? parseInt(data.pid);
            const productName = rpc.etiqueta?.produto_nome_snapshot || reconferirDialog.produto;
            const tipoEtq = rpc.etiqueta?.tipo_embalagem ?? data.tipo ?? null;
            const qtyEtq = Number(rpc.etiqueta?.quantidade_interna ?? data.qty ?? 1);
            const scanKey = data.uid || reconferirDialog.uid;

            setScannedUids(prev => new Set(prev).add(scanKey));
            setBoxes(prev => {
                let firstIdx = prev.findIndex(b => b.status === "pending" && b.produtoMasterId === scannedPid);
                if (firstIdx < 0) firstIdx = prev.findIndex(b => b.status === "pending" && productNamesMatch(b.productName, productName));
                if (firstIdx >= 0) {
                    const cardsCobertos = calcularIncrementoBip(prev[firstIdx].unidadeMedida, tipoEtq, qtyEtq);
                    const u = [...prev];
                    let marcados = 0;
                    for (let i = 0; i < u.length && marcados < cardsCobertos; i++) {
                        const matchByPid = scannedPid && u[i].produtoMasterId === scannedPid;
                        const matchByName = !matchByPid && productNamesMatch(u[i].productName, productName);
                        if (u[i].status === "pending" && (matchByPid || matchByName)) {
                            u[i] = { ...u[i], status: "confirmed", scannedData: marcados === 0 ? data : u[i].scannedData, scannedProductName: productName, scannedAt: Date.now() };
                            marcados++;
                        }
                    }
                    return u;
                }
                return [...prev, { cardId: `extra-${Date.now()}-${Math.random().toString(36).substring(7)}`, itemId: undefined, produtoMasterId: null, productName, boxNumber: 1, totalBoxes: 1, status: "extra" as const, scannedData: data, scannedProductName: productName, scannedAt: Date.now() }];
            });
            playSuccessSound();
            if (navigator.vibrate) navigator.vibrate(100);
            toast.success(`Conferência transferida: ${productName}`);
        } catch (e) {
            toast.error(`Erro: ${(e as Error).message}`);
            playErrorSound();
        } finally {
            setReconferirDialog({ open: false, uid: "", produto: "", conferida_at: null, data: null });
        }
    };

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => setScanBuffer(e.target.value);
    const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => { if (e.key === "Enter" && scanBuffer.trim()) { e.preventDefault(); handleScan(scanBuffer.trim()); } };

    const stats = useMemo(() => {
        const pending = boxes.filter(b => b.status === "pending");
        const confirmed = boxes.filter(b => b.status === "confirmed");
        const extra = boxes.filter(b => b.status === "extra");
        const total = boxes.filter(b => b.status !== "extra").length;
        return { pending, confirmed, extra, progress: total > 0 ? Math.round((confirmed.length / total) * 100) : 0 };
    }, [boxes]);

    const isComplete = stats.pending.length === 0 && stats.confirmed.length > 0;

    const handleDarSaida = async () => {
        if (!lojaPreparadoraId) {
            toast.error("Loja preparadora não identificada. Não é possível dar saída.");
            return;
        }
        const confirmed = boxes.filter(b => b.status === "confirmed" && b.produtoMasterId);
        if (confirmed.length === 0) {
            toast.error("Nenhum item conferido para dar saída.");
            return;
        }
        if (!confirm(`Dar saída de ${confirmed.length} item(ns) conferido(s) do estoque da fábrica?`)) return;

        setExitLoading(true);
        try {
            // Caixas COM etiqueta_qr (uid) viram movimentações 1:1, fechando o link
            // de rastreabilidade. Caixas SEM uid (legado / criadas manualmente) seguem
            // agrupadas por produto, comportamento original. Trigger atualizar_estoque_e_alertas
            // cuida do saldo em ambos os casos.
            const comUid = confirmed.filter(b => b.scannedData?.uid);
            const semUid = confirmed.filter(b => !b.scannedData?.uid);

            // Cache de saldo atual por produto pra calcular quantidade_anterior/nova em sequência
            const saldoCache = new Map<number, number>();
            const fetchSaldo = async (pid: number): Promise<number> => {
                if (saldoCache.has(pid)) return saldoCache.get(pid)!;
                const { data } = await supabase
                    .from("estoque")
                    .select("quantidade_atual")
                    .eq("produto_master_id", pid)
                    .eq("loja_id", lojaPreparadoraId)
                    .maybeSingle();
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                const v = (data as any)?.quantidade_atual ?? 0;
                saldoCache.set(pid, v);
                return v;
            };

            // UIDs que falharam no bip (rastreabilidade quebrada — movimentação
            // ainda ocorre pois o item está fisicamente saindo, mas operador
            // precisa saber para investigar/corrigir depois).
            const bipFalhasUids: string[] = [];

            // 1) Caixas com UID — bip 'saida' + movimentação individual com etiqueta_qr_uid
            for (const box of comUid) {
                const uid = box.scannedData!.uid!;
                const pid = box.produtoMasterId!;
                const loteId = box.scannedData?.lid || null;
                // Bulk items (kg, litro, etc.) usam qty física da etiqueta; caixas = 1
                const movQty = box.isBulkUnit ? (box.scannedData?.qty || box.bulkQty || 1) : 1;

                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                const { data: rpcRaw, error: rpcErr } = await (supabase.rpc as any)(
                    "bipar_etiqueta",
                    {
                        p_uid: uid,
                        p_etapa: "saida",
                        p_contexto: {
                            loja_id: lojaPreparadoraId,
                            referencia_tipo: "requisicao",
                            referencia_id: String(requisicaoId),
                            payload: box.scannedData,
                        },
                    }
                );
                const rpc = rpcRaw as { ok: boolean; erro?: string } | null;
                if (rpcErr || !rpc?.ok) {
                    // Etiqueta em status incompatível ou não cadastrada.
                    // Saída física continua (caminhão já vai), mas rastreabilidade
                    // fica incompleta — registra UID para operador investigar.
                    bipFalhasUids.push(uid);
                }

                const anterior = await fetchSaldo(pid);
                const nova = Math.max(0, anterior - movQty);
                saldoCache.set(pid, nova);

                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                const { error: movError } = await (supabase.from("movimentacoes") as any).insert({
                    produto_master_id: pid,
                    tipo_movimentacao: "saida",
                    quantidade: movQty,
                    quantidade_anterior: anterior,
                    quantidade_nova: nova,
                    motivo: "expedicao",
                    observacoes: `Saída via conferência - ${requisicaoNome} - UID ${uid}`,
                    data_movimentacao: new Date().toISOString(),
                    loja_id: lojaPreparadoraId,
                    lote_id: loteId || null,
                    etiqueta_qr_uid: uid,
                });
                if (movError) throw movError;
            }

            // 2) Sem UID — comportamento legado (grouped por produto)
            const grouped = new Map<number, { qty: number; loteId: string | null }>();
            semUid.forEach(box => {
                const pid = box.produtoMasterId!;
                const loteId = box.scannedData?.lid || null;
                // Bulk: usa bulkQty (quantidade_solicitada); caixas: += 1 por card
                const increment = box.isBulkUnit ? (box.bulkQty || 1) : 1;
                const existing = grouped.get(pid);
                if (existing) existing.qty += increment;
                else grouped.set(pid, { qty: increment, loteId });
            });

            for (const [pid, { qty, loteId }] of grouped) {
                const anterior = await fetchSaldo(pid);
                const nova = Math.max(0, anterior - qty);
                saldoCache.set(pid, nova);

                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                const { error: movError } = await (supabase.from("movimentacoes") as any).insert({
                    produto_master_id: pid,
                    tipo_movimentacao: "saida",
                    quantidade: qty,
                    quantidade_anterior: anterior,
                    quantidade_nova: nova,
                    motivo: "expedicao",
                    observacoes: `Saída via conferência - ${requisicaoNome}`,
                    data_movimentacao: new Date().toISOString(),
                    loja_id: lojaPreparadoraId,
                    lote_id: loteId || null,
                });
                if (movError) throw movError;
            }

            const totalProdutos = new Set(confirmed.map(b => b.produtoMasterId)).size;
            toast.success(
                `Saída registrada: ${confirmed.length} caixa(s) / ${totalProdutos} produto(s) debitados.`
            );
            if (bipFalhasUids.length > 0) {
                // Mostra os UIDs específicos pra operador poder rastrear
                const preview = bipFalhasUids.slice(0, 3).join(", ");
                const extra = bipFalhasUids.length > 3 ? ` +${bipFalhasUids.length - 3} outras` : "";
                toast.warning(
                    `${bipFalhasUids.length} etiqueta(s) saíram sem rastreio de status: ${preview}${extra}. Verifique via Auditoria.`
                );
            }
            localStorage.removeItem(getStorageKey(requisicaoId));
        } catch (e) {
            handleError(e, { domain: 'logistica', operation: 'darSaidaEstoque', showToast: false });
            toast.error("Erro ao registrar saída de estoque.");
        } finally {
            setExitLoading(false);
        }
    };

    const handleClose = () => { setScanBuffer(""); onClose(); };
    const handleReset = () => {
        if (!confirm("Tem certeza que deseja resetar toda a conferência? Todo o progresso será perdido.")) return;
        localStorage.removeItem(getStorageKey(requisicaoId));
        setBoxes(createBoxesFromItems(items));
        setScannedUids(new Set());
        toast.info("Conferência resetada");
    };

    return (
        <Dialog open={isOpen} onOpenChange={handleClose}>
            <DialogContent data-mia-modal="confer-ncia-bip" className="max-w-[98vw] w-full h-[95vh] p-0 flex flex-col overflow-hidden bg-background rounded-[1.5rem]">

                {/* ── Header ── */}
                <div className="flex items-center justify-between px-5 py-3 flex-shrink-0 border-b border-border/50">
                    <div className="flex items-center gap-3">
                        <Button data-mia-action="close" variant="ghost" size="icon" onClick={handleClose} className="rounded-2xl hover:bg-[#57715B]/10">
                            <ArrowLeft className="w-5 h-5 text-[#57715B]" />
                        </Button>
                        <div className="h-10 w-10 rounded-2xl bg-[#57715B]/10 flex items-center justify-center">
                            <ScanBarcode className="h-5 w-5 text-[#57715B]" />
                        </div>
                        <div>
                            <DialogTitle className="text-lg font-bold text-[#57715B] dark:text-[#E6DCCF]">Conferência / Bip</DialogTitle>
                            <p className="text-xs text-muted-foreground truncate max-w-[280px]">{requisicaoNome}</p>
                        </div>
                    </div>

                    <div className="flex items-center gap-2">
                        {/* Reset button */}
                        <Button data-mia-action="reset" variant="ghost" size="icon" onClick={handleReset} className="rounded-2xl hover:bg-red-500/10 text-muted-foreground hover:text-red-600" title="Resetar conferência">
                            <RotateCcw className="w-4 h-4" />
                        </Button>
                        {/* Toggle (same as Scanner.tsx) */}
                        <div className="flex p-1 rounded-xl bg-muted/50 dark:bg-zinc-800">
                            <button onClick={() => setScanMode("bluetooth")} className={cn(
                                "px-4 py-2 text-sm font-medium rounded-lg flex items-center gap-2 transition-all",
                                scanMode === "bluetooth" ? "bg-white dark:bg-zinc-700 text-[#57715B] shadow-sm" : "text-muted-foreground hover:text-foreground"
                            )}>
                                <Bluetooth className="h-4 w-4" /> Scanner
                            </button>
                            <button onClick={() => setScanMode("camera")} className={cn(
                                "px-4 py-2 text-sm font-medium rounded-lg flex items-center gap-2 transition-all",
                                scanMode === "camera" ? "bg-white dark:bg-zinc-700 text-[#57715B] shadow-sm" : "text-muted-foreground hover:text-foreground"
                            )}>
                                <Camera className="h-4 w-4" /> Câmera
                            </button>
                        </div>
                    </div>
                </div>

                {/* ── Progress ── */}
                <div className="px-5 py-3 flex-shrink-0 border-b border-border/50">
                    <div className="flex items-center justify-between mb-2">
                        <span className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground">Progresso</span>
                        <span className={cn("text-xl font-black tabular-nums", isComplete ? "text-emerald-600" : "text-[#57715B]")}>{stats.progress}%</span>
                    </div>
                    <div className="w-full h-2.5 bg-[#57715B]/10 dark:bg-white/10 rounded-full overflow-hidden">
                        <div className={cn(
                            "h-full rounded-full transition-all duration-700 ease-out",
                            isComplete ? "bg-emerald-500 shadow-[0_0_12px_rgba(16,185,129,0.5)]" : "bg-[#57715B]"
                        )} style={{ width: `${stats.progress}%` }} />
                    </div>
                    <div className="flex items-center gap-5 mt-2">
                        <span className="flex items-center gap-1.5 text-xs"><span className="w-2.5 h-2.5 rounded-full bg-red-500" /> Pendentes <b>{stats.pending.length}</b></span>
                        <span className="flex items-center gap-1.5 text-xs"><span className="w-2.5 h-2.5 rounded-full bg-emerald-500" /> Conferidos <b>{stats.confirmed.length}</b></span>
                        {stats.extra.length > 0 && <span className="flex items-center gap-1.5 text-xs"><span className="w-2.5 h-2.5 rounded-full bg-orange-500" /> Extras <b>{stats.extra.length}</b></span>}
                    </div>
                </div>

                {/* Hidden input for external scanner */}
                {scanMode === "bluetooth" && (
                    <input ref={inputRef} type="text" value={scanBuffer} onChange={handleInputChange} onKeyDown={handleKeyDown} className="opacity-0 absolute top-0 left-0 w-0 h-0" autoFocus />
                )}

                {/* ── Main: Scanner + Kanban ── */}
                <div className="flex-1 flex flex-col md:flex-row overflow-hidden">

                    {/* Scanner panel */}
                    {scanMode === "camera" ? (
                        <div className="w-full md:w-[260px] flex-shrink-0 border-b md:border-b-0 md:border-r border-border/50 bg-black overflow-hidden">
                            <div id="conferencia-qr-reader" className="w-full h-[200px] md:h-full" />
                        </div>
                    ) : (
                        <div className="w-full md:w-[200px] flex-shrink-0 border-b md:border-b-0 md:border-r border-border/50 flex flex-col items-center justify-center p-5 cursor-pointer" onClick={() => inputRef.current?.focus()}>
                            <div className="w-20 h-20 rounded-full bg-[#57715B]/10 flex items-center justify-center relative">
                                <Bluetooth className="w-9 h-9 text-[#57715B]" />
                                <div className="absolute inset-0 rounded-full border-[3px] border-[#57715B]/20 border-t-[#57715B] animate-spin" style={{ animationDuration: "3s" }} />
                            </div>
                            <h3 className="text-sm font-bold text-[#57715B] dark:text-[#E6DCCF] mt-4">Escaneando...</h3>
                            <p className="text-[11px] text-muted-foreground text-center mt-1">Aponte o leitor para as etiquetas</p>
                        </div>
                    )}

                    {/* ══ KANBAN BOARD ══ */}
                    <div className="flex-1 flex overflow-hidden p-2 gap-2">

                        {/* 🔴 PENDENTES - Red glow column */}
                        <div className={cn(
                            "flex-1 flex flex-col min-w-0 rounded-[1.5rem] overflow-hidden",
                            "border-2 border-red-500/60 dark:border-red-400/50",
                            "bg-white/20 dark:bg-white/5 backdrop-blur-md",
                            "shadow-[0_0_15px_-3px_rgba(239,68,68,0.3),inset_0_0_20px_-10px_rgba(239,68,68,0.1)]",
                            "dark:shadow-[0_0_20px_-3px_rgba(239,68,68,0.4),inset_0_0_30px_-10px_rgba(239,68,68,0.15)]"
                        )}>
                            <div className="px-4 py-3 border-b border-red-400/30 dark:border-red-400/20 flex items-center justify-between">
                                <div className="flex items-center gap-2">
                                    <XCircle className="w-4 h-4 text-red-600 dark:text-red-400" />
                                    <span className="text-xs font-bold uppercase tracking-wider text-red-600 dark:text-red-400">Pendentes</span>
                                </div>
                                <span className="text-sm font-black text-red-600 dark:text-red-400">{stats.pending.length}</span>
                            </div>
                            <ScrollArea className="flex-1">
                                <div className="p-2.5 space-y-2">
                                    {stats.pending.length === 0 ? (
                                        <div className="flex flex-col items-center justify-center py-16 text-emerald-500/40">
                                            <CheckCircle2 className="w-12 h-12 mb-2" />
                                            <p className="text-sm font-semibold">Todos conferidos!</p>
                                        </div>
                                    ) : stats.pending.map(box => (
                                        <BoxCardItem key={box.cardId} box={box} />
                                    ))}
                                </div>
                            </ScrollArea>
                        </div>

                        {/* 🟢 CONFERIDOS - Green glow column */}
                        <div className={cn(
                            "flex-1 flex flex-col min-w-0 rounded-[1.5rem] overflow-hidden",
                            "border-2 border-green-500/60 dark:border-green-400/50",
                            "bg-white/20 dark:bg-white/5 backdrop-blur-md",
                            "shadow-[0_0_15px_-3px_rgba(34,197,94,0.3),inset_0_0_20px_-10px_rgba(34,197,94,0.1)]",
                            "dark:shadow-[0_0_20px_-3px_rgba(34,197,94,0.4),inset_0_0_30px_-10px_rgba(34,197,94,0.15)]"
                        )}>
                            <div className="px-4 py-3 border-b border-green-400/30 dark:border-green-400/20 flex items-center justify-between">
                                <div className="flex items-center gap-2">
                                    <CheckCircle2 className="w-4 h-4 text-green-600 dark:text-green-400" />
                                    <span className="text-xs font-bold uppercase tracking-wider text-green-600 dark:text-green-400">Conferidos</span>
                                </div>
                                <span className="text-sm font-black text-green-600 dark:text-green-400">{stats.confirmed.length}</span>
                            </div>
                            <ScrollArea className="flex-1">
                                <div className="p-2.5 space-y-2">
                                    {stats.confirmed.length === 0 ? (
                                        <div className="flex flex-col items-center justify-center py-16 text-green-400/30">
                                            <QrCode className="w-12 h-12 mb-2" />
                                            <p className="text-sm font-semibold">Bipe para conferir</p>
                                        </div>
                                    ) : [...stats.confirmed].sort((a, b) => (b.scannedAt || 0) - (a.scannedAt || 0)).map(box => (
                                        <BoxCardItem key={box.cardId} box={box} />
                                    ))}
                                </div>
                            </ScrollArea>
                        </div>

                        {/* 🟠 FORA DA LISTA - Orange glow column */}
                        <div className={cn(
                            "flex-1 flex flex-col min-w-0 rounded-[1.5rem] overflow-hidden",
                            "border-2 border-orange-500/60 dark:border-orange-400/50",
                            "bg-white/20 dark:bg-white/5 backdrop-blur-md",
                            "shadow-[0_0_15px_-3px_rgba(249,115,22,0.3),inset_0_0_20px_-10px_rgba(249,115,22,0.1)]",
                            "dark:shadow-[0_0_20px_-3px_rgba(249,115,22,0.4),inset_0_0_30px_-10px_rgba(249,115,22,0.15)]"
                        )}>
                            <div className="px-4 py-3 border-b border-orange-400/30 dark:border-orange-400/20 flex items-center justify-between">
                                <div className="flex items-center gap-2">
                                    <AlertTriangle className="w-4 h-4 text-orange-600 dark:text-orange-400" />
                                    <span className="text-xs font-bold uppercase tracking-wider text-orange-600 dark:text-orange-400">Fora da Lista</span>
                                </div>
                                <span className="text-sm font-black text-orange-600 dark:text-orange-400">{stats.extra.length}</span>
                            </div>
                            <ScrollArea className="flex-1">
                                <div className="p-2.5 space-y-2">
                                    {stats.extra.length === 0 ? (
                                        <div className="flex flex-col items-center justify-center py-16 text-orange-400/30">
                                            <Package className="w-12 h-12 mb-2" />
                                            <p className="text-xs text-center font-medium px-4">Itens bipados que não estão na requisição aparecerão aqui</p>
                                        </div>
                                    ) : [...stats.extra].sort((a, b) => (b.scannedAt || 0) - (a.scannedAt || 0)).map(box => (
                                        <BoxCardItem key={box.cardId} box={box} />
                                    ))}
                                </div>
                            </ScrollArea>
                        </div>
                    </div>
                </div>

                {/* ── Footer ── */}
                {stats.confirmed.length > 0 && (
                    <div className={cn(
                        "px-5 py-3 flex-shrink-0 border-t border-border/50 flex items-center gap-3 animate-in slide-in-from-bottom duration-500",
                        isComplete && stats.extra.length === 0
                            ? "bg-emerald-50 dark:bg-emerald-950/30"
                            : isComplete
                                ? "bg-orange-50 dark:bg-orange-950/30"
                                : "bg-background"
                    )}>
                        <div className="flex-1 min-w-0">
                            {isComplete && stats.extra.length === 0 && (
                                <div className="flex items-center gap-2 text-emerald-700 dark:text-emerald-400 text-sm font-semibold">
                                    <CheckCircle2 className="w-4 h-4 flex-shrink-0" />
                                    Conferência completa! Todos os itens verificados.
                                </div>
                            )}
                            {isComplete && stats.extra.length > 0 && (
                                <div className="flex items-center gap-2 text-orange-700 dark:text-orange-400 text-sm font-semibold">
                                    <AlertTriangle className="w-4 h-4 flex-shrink-0" />
                                    Completo, mas {stats.extra.length} item(ns) fora da lista!
                                </div>
                            )}
                            {!isComplete && (
                                <span className="text-xs text-muted-foreground">{stats.confirmed.length} item(ns) prontos para saída</span>
                            )}
                        </div>
                        <Button data-mia-action="dar-saida"
                            onClick={handleDarSaida}
                            disabled={exitLoading}
                            className="flex-shrink-0 bg-[#57715B] hover:bg-[#4A614E] text-white shadow-md"
                        >
                            {exitLoading
                                ? <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                                : <PackageMinus className="w-4 h-4 mr-2" />
                            }
                            Dar Saída ({stats.confirmed.length})
                        </Button>
                    </div>
                )}
            </DialogContent>

            {/* AlertDialog — transferir conferencia de outra requisicao */}
            <AlertDialog open={reconferirDialog.open} onOpenChange={(o) => !o && setReconferirDialog({ open: false, uid: "", produto: "", conferida_at: null, data: null })}>
                <AlertDialogContent className="max-w-md rounded-3xl">
                    <AlertDialogHeader>
                        <AlertDialogTitle className="text-lg font-bold text-orange-700 flex items-center gap-2">
                            <AlertTriangle className="w-5 h-5" />
                            Etiqueta já conferida
                        </AlertDialogTitle>
                        <AlertDialogDescription asChild>
                            <div className="space-y-3 text-sm">
                                <p>
                                    <b className="text-foreground">{reconferirDialog.produto}</b> já foi conferida{" "}
                                    {reconferirDialog.conferida_at && (
                                        <span className="text-foreground">
                                            em <b>{new Date(reconferirDialog.conferida_at).toLocaleString("pt-BR", { day: "2-digit", month: "2-digit", hour: "2-digit", minute: "2-digit" })}</b>
                                        </span>
                                    )} (em outra requisição).
                                </p>
                                <p className="text-orange-700 font-semibold">
                                    Deseja transferir a conferência para esta requisição?
                                </p>
                                <p className="text-xs text-muted-foreground">
                                    A etiqueta passa a contar para esta requisição. O histórico fica registrado na timeline.
                                </p>
                            </div>
                        </AlertDialogDescription>
                    </AlertDialogHeader>
                    <AlertDialogFooter>
                        <AlertDialogCancel className="rounded-xl">Cancelar</AlertDialogCancel>
                        <AlertDialogAction onClick={confirmarReconferir} className="bg-orange-600 hover:bg-orange-700 rounded-xl">
                            Transferir conferência
                        </AlertDialogAction>
                    </AlertDialogFooter>
                </AlertDialogContent>
            </AlertDialog>
        </Dialog>
    );
}

