function BoxCardItem({ box }: { box: BoxCard }) {
    const isPending = box.status === "pending";
    const isConfirmed = box.status === "confirmed";
    const isExtra = box.status === "extra";

    const borderHex = isConfirmed ? "#10B981" : isExtra ? "#F97316" : "#EF4444";
    const glowClass = isConfirmed
        ? "shadow-[0_0_16px_rgba(16,185,129,0.2)]"
        : isExtra
            ? "shadow-[0_0_16px_rgba(249,115,22,0.2)]"
            : "";

    return (
        <div
            className={cn(
                "rounded-xl p-3 border-[1.5px] transition-all relative overflow-hidden",
                "bg-white dark:bg-zinc-900",
                (isConfirmed || isExtra) && "animate-in slide-in-from-left-8 duration-500",
                glowClass
            )}
            style={{ borderColor: borderHex }}
        >
            {/* Gradient overlay */}
            <div className={cn(
                "absolute inset-0 rounded-xl pointer-events-none",
                isPending && "bg-gradient-to-tl from-red-200/15 via-transparent to-transparent",
                isConfirmed && "bg-gradient-to-tl from-emerald-200/20 via-transparent to-transparent",
                isExtra && "bg-gradient-to-tl from-orange-200/20 via-transparent to-transparent"
            )} />

            <div className="relative flex items-start gap-2.5">
                {/* Status icon */}
                <div className={cn(
                    "w-7 h-7 rounded-xl flex items-center justify-center flex-shrink-0",
                    isPending && "bg-red-500/10",
                    isConfirmed && "bg-emerald-500/15",
                    isExtra && "bg-orange-500/15"
                )}>
                    {isPending && <Box className="w-3.5 h-3.5 text-red-500" />}
                    {isConfirmed && <CheckCircle2 className="w-3.5 h-3.5 text-emerald-600" />}
                    {isExtra && <AlertTriangle className="w-3.5 h-3.5 text-orange-600" />}
                </div>

                <div className="flex-1 min-w-0">
                    <p className={cn(
                        "text-xs font-semibold leading-tight truncate text-[#2D362E] dark:text-white",
                        isPending && "opacity-70"
                    )}>
                        {box.productName}
                    </p>
                    <div className="flex items-center gap-1.5 mt-1 flex-wrap">
                        <span className={cn(
                            "inline-flex items-center gap-1 px-1.5 py-0.5 rounded-md text-[10px] font-bold border",
                            isPending && "bg-red-500/10 text-red-600 border-red-300/40",
                            isConfirmed && "bg-emerald-500/10 text-emerald-700 border-emerald-300/40",
                            isExtra && "bg-orange-500/10 text-orange-700 border-orange-300/40"
                        )}>
                            <Box className="w-2.5 h-2.5" />
                            {box.isBulkUnit
                                ? `${box.bulkQty ?? box.scannedData?.qty ?? '?'} ${(box.unidadeMedida || '').toUpperCase()}`
                                : `${(box.unidadeMedida || 'caixa').toUpperCase()} ${box.boxNumber}/${box.totalBoxes}`
                            }
                        </span>
                        {box.category && (
                            <span className="text-[10px] text-muted-foreground bg-muted/50 dark:bg-zinc-800 px-1.5 py-0.5 rounded-md border border-border/50 truncate max-w-[80px]">
                                {box.category}
                            </span>
                        )}
                        {box.scannedData?.lote && (
                            <span className="text-[10px] font-mono text-muted-foreground bg-muted/50 dark:bg-zinc-800 px-1.5 py-0.5 rounded-md border border-border/50">
                                L: {box.scannedData.lote}
                            </span>
                        )}
                        {box.scannedData?.emb && (
                            <span className="text-[10px] text-muted-foreground bg-muted/50 dark:bg-zinc-800 px-1.5 py-0.5 rounded-md border border-border/50">
                                {box.scannedData.emb}
                            </span>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}

