358	            </div>
359	            <div className="min-w-0 flex-1">
360	              <DialogTitle className="text-base sm:text-lg font-bold text-[#57715B] dark:text-[#8FAE94] truncate">
361	                Conferir chegada · {requisicaoNome}
362	              </DialogTitle>
