394	        </div>
395	
396	        {/* Stats */}
397	        <div className="px-3 sm:px-5 py-3 flex-shrink-0 border-b border-[#57715B]/10 grid grid-cols-2 sm:grid-cols-4 gap-2 sm:gap-3">
