554	                  <label className="text-xs uppercase tracking-wider font-bold text-muted-foreground block mb-1">
555	                    Quantidade recebida (un)
556	                  </label>
557	                  <Input
558	                    type="number"
559	                    min="0"
560	                    step="any"
561	                    value={manual.quantidade}
562	                    onChange={(e) => setManual((s) => ({ ...s, quantidade: e.target.value }))}
563	                    autoFocus
564	                    className="h-11 text-lg font-bold bg-white/60 dark:bg-black/20 border-[#57715B]/20 focus-visible:ring-[#57715B]/30"
565	                  />
566	                </div>
567	                <p className="text-xs text-amber-700 bg-amber-50 dark:bg-amber-900/20 rounded-md p-2">
568	                  Marcar manual NÃO gera movimentação de estoque automática (sem etiqueta = sem
569	                  rastreabilidade).
570	                </p>
571	              </div>
572	            </AlertDialogDescription>
573	          </AlertDialogHeader>
574	          <AlertDialogFooter>
575	            <AlertDialogCancel
576	              onClick={() => setManual((s) => ({ ...s, open: false }))}
577	              className="border-[#57715B]/20 hover:bg-[#57715B]/10"
578	            >
579	              Cancelar
580	            </AlertDialogCancel>
581	            <AlertDialogAction
582	              onClick={() => void confirmManual()}
583	              className="bg-[#57715B] hover:bg-[#465b49] text-white"
584	            >
585	              Confirmar
586	            </AlertDialogAction>
587	          </AlertDialogFooter>
588	        </AlertDialogContent>
589	      </AlertDialog>
590	    </Dialog>
591	  );
592	}
593	
594	function Stat({
595	  label,
596	  value,
597	  icon,
598	}: {
599	  label: string;
600	  value: string | number;
601	  icon?: React.ReactNode;
602	}) {
603	  return (
604	    <div className="text-center min-w-0">
605	      <p className="text-[9px] sm:text-[10px] uppercase tracking-widest text-muted-foreground font-bold truncate flex items-center gap-1 justify-center">
606	        {icon}
607	        {label}
608	      </p>
609	      <p className="text-xl sm:text-2xl font-black tabular-nums text-[#57715B]">{value}</p>
610	    </div>
611	  );
612	}
613	
614	function ItemRow({
615	  item,
616	  onMarcarManual,
617	}: {
618	  item: ChegadaItem;
619	  onMarcarManual: () => void;
620	}) {
621	  const recebido = Number(item.quantidade_recebida || "0") || 0;
622	  const solicitado = item.quantidade_solicitada || 0;
623	  const enviado = Number(item.quantidade_enviada || "0") || 0;
624	  const pct = solicitado > 0 ? Math.min(100, Math.round((recebido / solicitado) * 100)) : 0;
625	  const status: "vazio" | "parcial" | "completo" | "excesso" =
626	    recebido === 0
627	      ? "vazio"
628	      : recebido > solicitado
629	        ? "excesso"
630	        : recebido >= solicitado
631	          ? "completo"
632	          : "parcial";
633	  const ring =
634	    status === "completo"
635	      ? "border-emerald-500/40 bg-emerald-500/5"
636	      : status === "excesso"
637	        ? "border-amber-500/40 bg-amber-500/5"
638	        : status === "parcial"
639	          ? "border-[#57715B]/30 bg-[#57715B]/5"
640	          : "border-white/30 dark:border-white/10";
641	  const bg =
642	    status === "completo"
643	      ? "bg-emerald-500"
644	      : status === "excesso"
645	        ? "bg-amber-500"
646	        : status === "parcial"
647	          ? "bg-[#57715B]"
648	          : "bg-zinc-300 dark:bg-zinc-700";
649	  return (
650	    <div className={cn("rounded-xl border-2 p-3", ring)}>
651	      <div className="flex items-start justify-between gap-2 mb-1.5">
652	        <div className="min-w-0 flex-1">
653	          <p className="text-sm font-semibold leading-tight truncate flex items-center gap-2">
654	            {status === "completo" && (
655	              <CheckCircle2 className="w-4 h-4 text-emerald-600 flex-shrink-0" />
656	            )}
657	            {status === "excesso" && (
658	              <AlertTriangle className="w-4 h-4 text-amber-600 flex-shrink-0" />
659	            )}
660	            <span className="truncate">{item.nome_produto}</span>
661	          </p>
662	          <p className="text-[11px] text-muted-foreground mt-0.5">
663	            Pedido <b>{solicitado}</b> un · Expedido <b>{enviado || 0}</b> un
664	            {item.recebida_via && (
665	              <span
666	                className={cn(
667	                  "ml-2 inline-block px-1.5 py-0.5 rounded text-[9px] font-bold uppercase tracking-wider",
668	                  item.recebida_via === "bip"
669	                    ? "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-300"
670	                    : "bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-300",
671	                )}
672	              >
673	                {item.recebida_via}
674	              </span>
675	            )}
676	          </p>
677	        </div>
678	        <div className="flex items-center gap-2 flex-shrink-0">
679	          <span
680	            className={cn(
681	              "text-sm font-bold tabular-nums",
682	              status === "completo"
683	                ? "text-emerald-700"
684	                : status === "excesso"
685	                  ? "text-amber-700"
686	                  : "text-foreground",
687	            )}
688	          >
689	            {recebido}/{solicitado}
690	          </span>
691	          <Button
692	            data-mia-action="marcar-manual"
693	            size="sm"
694	            variant="outline"
695	            className="h-8 gap-1 text-[11px] border-[#57715B]/20 hover:bg-[#57715B]/10"
696	            onClick={onMarcarManual}
697	          >
698	            <Hand className="w-3 h-3" /> Manual
699	          </Button>
700	        </div>
701	      </div>
702	      <div className="w-full h-1.5 bg-zinc-100 dark:bg-zinc-800 rounded-full overflow-hidden">
703	        <div
704	          className={cn("h-full rounded-full transition-all duration-500", bg)}
705	          style={{ width: `${pct}%` }}
706	        />
707	      </div>
708	    </div>
709	  );
710	}
