1	/**
2	 * Página /requisicoes/chegada — operador da loja confere a chegada das requisições.
3	 *
4	 * Mostra todas as requisições onde a loja_solicitante == loja do usuário
5	 * que ainda não foram concluídas (chegada_concluida_at IS NULL). Card-list,
6	 * cada card abre RequisicaoChegadaModal com os itens da requisição.
7	 */
8	import { useEffect, useMemo, useState } from "react";
9	import { useNavigate } from "react-router-dom";
10	import { ArrowLeft, Package, Truck, MapPin, Calendar, CheckCircle2, AlertTriangle, Leaf } from "lucide-react";
11	import { format } from "date-fns";
12	import { ptBR } from "date-fns/locale";
13	
14	import { Button } from "@/shared/ui/button";
15	import { Card, CardContent, CardHeader, CardTitle } from "@/shared/ui/card";
16	import { Badge } from "@/shared/ui/badge";
17	import { Skeleton } from "@/shared/ui/skeleton";
18	import { useStore } from "@/shared/contexts/StoreContext";
19	import { supabase } from "@/integrations/supabase/client";
20	import { cn } from "@/shared/lib/utils";
21	import {
22	  RequisicaoChegadaModal,
23	  type ChegadaItem,
24	} from "@/features/requisicoes/ui/RequisicaoChegadaModal";
25	
26	interface ReqChegada {
27	  id: number;
28	  nome: string;
29	  loja_solicitante: string;
30	  loja_preparadora: string;
31	  data_pedido: string;
32	  data_recebimento: string;
33	  status: string | null;
34	  chegada_iniciada_at: string | null;
35	  chegada_concluida_at: string | null;
36	}
37	
38	interface ProdutoNomeMap { id: number; nome: string; }
39	
40	function fmtDate(iso: string | null): string {
41	  if (!iso) return "—";
42	  try {
43	    return format(new Date(iso), "dd/MM/yyyy", { locale: ptBR });
44	  } catch { return iso; }
45	}
46	
47	export default function RequisicaoChegadaPage() {
48	  const navigate = useNavigate();
49	  const { selectedStore } = useStore();
50	
51	  const [reqs, setReqs] = useState<ReqChegada[]>([]);
52	  const [loading, setLoading] = useState(true);
53	  const [modalOpen, setModalOpen] = useState(false);
54	  const [modalItems, setModalItems] = useState<ChegadaItem[]>([]);
55	  const [modalReq, setModalReq] = useState<ReqChegada | null>(null);
56	
57	  // Loja atual: id + nome
58	  const [lojaId, setLojaId] = useState<number | null>(null);
59	  const [lojaNome, setLojaNome] = useState<string>("");
60	
61	  useEffect(() => {
62	    if (!selectedStore) return;
63	    setLojaId(selectedStore.id);
64	    setLojaNome(selectedStore.name);
65	  }, [selectedStore]);
66	
67	  const loadReqs = async () => {
68	    if (!lojaNome) return;
69	    setLoading(true);
70	    const { data, error } = await supabase
71	      .from("requisicoes")
72	      // eslint-disable-next-line @typescript-eslint/no-explicit-any
73	      .select("id, nome, loja_solicitante, loja_preparadora, data_pedido, data_recebimento, status, chegada_iniciada_at, chegada_concluida_at" as any)
74	      .ilike("loja_solicitante", `%${lojaNome}%`)
75	      .is("chegada_concluida_at", null)
76	      .order("data_recebimento", { ascending: true })
77	      .limit(50);
78	    if (error) {
79	      setLoading(false);
80	      return;
81	    }
82	    setReqs((data || []) as unknown as ReqChegada[]);
83	    setLoading(false);
84	  };
85	
86	  useEffect(() => {
87	    if (lojaNome) loadReqs();
88	    // eslint-disable-next-line react-hooks/exhaustive-deps
89	  }, [lojaNome]);
90	
91	  const openModal = async (req: ReqChegada) => {
92	    // Carrega itens + resolve produto_master_id por nome
93	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
94	    const { data: rawItens } = await (supabase
95	      .from("requisicoes_itens") as any)
96	      .select("id, nome_produto, quantidade_solicitada, quantidade_enviada, quantidade_recebida, recebida_via, recebida_at, ordem")
97	      .eq("requisicao_id", req.id)
98	      .order("ordem", { ascending: true });
99	
100	    const itens = (rawItens || []) as Array<{
101	      id: number;
102	      nome_produto: string;
103	      quantidade_solicitada: number;
104	      quantidade_enviada: string | null;
105	      quantidade_recebida: string | null;
106	      recebida_via: "bip" | "manual" | null;
107	      recebida_at: string | null;
108	    }>;
109	
110	    const nomesUnicos = Array.from(new Set(itens.map((i) => i.nome_produto)));
111	    const { data: produtos } = await supabase
112	      .from("produtos_master")
113	      .select("id, nome")
114	      .in("nome", nomesUnicos);
115	
116	    const map = new Map<string, number>();
117	    ((produtos || []) as ProdutoNomeMap[]).forEach((p) => map.set(p.nome.toLowerCase().trim(), p.id));
118	
119	    const chegadaItems: ChegadaItem[] = itens.map((it) => ({
120	      id: it.id,
121	      nome_produto: it.nome_produto,
122	      masterId: map.get(it.nome_produto.toLowerCase().trim()) ?? null,
123	      quantidade_solicitada: Number(it.quantidade_solicitada || 0),
124	      quantidade_enviada: String(it.quantidade_enviada || ""),
125	      quantidade_recebida: String(it.quantidade_recebida || ""),
126	      recebida_via: it.recebida_via,
127	      recebida_at: it.recebida_at,
128	    }));
129	
130	    setModalItems(chegadaItems);
131	    setModalReq(req);
132	    setModalOpen(true);
133	  };
134	
135	  const stats = useMemo(() => {
136	    const total = reqs.length;
137	    const iniciadas = reqs.filter((r) => r.chegada_iniciada_at).length;
138	    return { total, iniciadas };
139	  }, [reqs]);
140	
141	  return (
142	    <div className="min-h-screen w-full bg-white dark:bg-[#0A0A0A] font-sans relative overflow-x-hidden transition-colors duration-300">
143	      {/* Faixa de toldo */}
144	      <div className="absolute top-0 left-0 right-0 h-1.5 bg-[repeating-linear-gradient(90deg,#57715B,#57715B_20px,#ffffff_20px,#ffffff_40px)] opacity-80 z-50 shadow-sm" />
145	      {/* Folhas decorativas */}
146	      <div className="fixed top-[-5%] right-[-10%] md:right-[-5%] w-[300px] md:w-[500px] h-[300px] md:h-[500px] opacity-[0.03] dark:opacity-[0.05] pointer-events-none animate-pulse" style={{ animationDuration: "10s" }}>
147	        <Leaf className="w-full h-full text-[#57715B] rotate-12" />
148	      </div>
149	      <div className="fixed bottom-[-10%] left-[-15%] md:left-[-5%] w-[400px] md:w-[600px] h-[400px] md:h-[600px] opacity-[0.03] dark:opacity-[0.05] pointer-events-none animate-pulse delay-1000" style={{ animationDuration: "12s" }}>
150	        <Leaf className="w-full h-full text-[#57715B] -rotate-45" />
151	      </div>
152	      {/* Brilhos ambientes */}
153	      <div className="fixed top-[20%] left-[10%] w-[200px] md:w-[400px] h-[200px] md:h-[400px] bg-[#57715B]/5 rounded-full blur-[80px] pointer-events-none" />
154	      <div className="fixed bottom-[30%] right-[10%] w-[250px] md:w-[500px] h-[250px] md:h-[500px] bg-[#C5A065]/5 rounded-full blur-[80px] pointer-events-none" />
155	
156	      <div className="relative z-10 flex flex-col gap-4 sm:gap-6 px-4 sm:px-6 py-6 md:py-8 max-w-5xl mx-auto w-full">
157	      {/* Header */}
158	      <div className="flex flex-col md:flex-row md:items-center justify-between gap-3 bg-white/50 dark:bg-zinc-900/50 p-4 sm:p-6 rounded-3xl border border-[#57715B]/10 backdrop-blur-md">
159	        <div className="flex items-center gap-3 sm:gap-4">
160	          <Button variant="ghost" size="sm" onClick={() => navigate(-1)} className="gap-2 min-h-[44px]">
161	            <ArrowLeft className="w-4 h-4" /> Voltar
162	          </Button>
163	          <div className="h-12 w-12 rounded-2xl bg-[#57715B]/10 flex items-center justify-center">
164	            <Truck className="h-6 w-6 text-[#57715B]" />
165	          </div>
166	          <div>
167	            <h1 className="text-xl sm:text-2xl font-bold text-[#57715B] dark:text-[#E6DCCF]">Conferência de Chegada</h1>
168	            <p className="text-xs sm:text-sm text-muted-foreground flex items-center gap-1">
169	              <MapPin className="w-3 h-3" /> {lojaNome || "Selecione uma loja"} · {stats.total} pendente(s)
170	            </p>
171	          </div>
172	        </div>
173	      </div>
174	
175	      {!lojaId && (
176	        <Card className="border-amber-300 bg-amber-50/50">
177	          <CardContent className="p-4 flex items-center gap-3 text-amber-800">
178	            <AlertTriangle className="w-5 h-5" />
179	            <p className="text-sm">Selecione uma loja no menu superior pra ver as chegadas pendentes.</p>
180	          </CardContent>
181	        </Card>
182	      )}
183	
184	      {loading && lojaId && (
185	        <div className="space-y-2">
186	          <Skeleton className="h-32 w-full" />
187	          <Skeleton className="h-32 w-full" />
188	        </div>
189	      )}
190	
191	      {!loading && lojaId && reqs.length === 0 && (
192	        <Card className="border-[#57715B]/20 bg-white/60 dark:bg-black/20 backdrop-blur-md rounded-3xl">
193	          <CardContent className="p-8 text-center text-muted-foreground">
194	            <CheckCircle2 className="w-10 h-10 mx-auto mb-2 opacity-40 text-emerald-500" />
195	            <p className="text-sm font-semibold">Sem chegadas pendentes</p>
196	            <p className="text-xs mt-1">Quando uma requisição da {lojaNome} estiver a caminho, ela aparece aqui.</p>
197	          </CardContent>
198	        </Card>
199	      )}
