/**
 * Página /requisicoes/chegada — operador da loja confere a chegada das requisições.
 *
 * Mostra todas as requisições onde a loja_solicitante == loja do usuário
 * que ainda não foram concluídas (chegada_concluida_at IS NULL). Card-list,
 * cada card abre RequisicaoChegadaModal com os itens da requisição.
 */
import { useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import { ArrowLeft, Package, Truck, MapPin, Calendar, CheckCircle2, AlertTriangle, Leaf } from "lucide-react";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";

import { Button } from "@/shared/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/shared/ui/card";
import { Badge } from "@/shared/ui/badge";
import { Skeleton } from "@/shared/ui/skeleton";
import { useStore } from "@/shared/contexts/StoreContext";
import { supabase } from "@/integrations/supabase/client";
import { cn } from "@/shared/lib/utils";
import {
  RequisicaoChegadaModal,
  type ChegadaItem,
} from "@/features/requisicoes/ui/RequisicaoChegadaModal";

interface ReqChegada {
  id: number;
  nome: string;
  loja_solicitante: string;
  loja_preparadora: string;
  data_pedido: string;
  data_recebimento: string;
  status: string | null;
  chegada_iniciada_at: string | null;
  chegada_concluida_at: string | null;
}

interface ProdutoNomeMap { id: number; nome: string; }

function fmtDate(iso: string | null): string {
  if (!iso) return "—";
  try {
    return format(new Date(iso), "dd/MM/yyyy", { locale: ptBR });
  } catch { return iso; }
}

export default function RequisicaoChegadaPage() {
  const navigate = useNavigate();
  const { selectedStore } = useStore();

  const [reqs, setReqs] = useState<ReqChegada[]>([]);
  const [loading, setLoading] = useState(true);
  const [modalOpen, setModalOpen] = useState(false);
  const [modalItems, setModalItems] = useState<ChegadaItem[]>([]);
  const [modalReq, setModalReq] = useState<ReqChegada | null>(null);

  // Loja atual: id + nome
  const [lojaId, setLojaId] = useState<number | null>(null);
  const [lojaNome, setLojaNome] = useState<string>("");

  useEffect(() => {
    if (!selectedStore) return;
    setLojaId(selectedStore.id);
    setLojaNome(selectedStore.name);
  }, [selectedStore]);

  const loadReqs = async () => {
    if (!lojaNome) return;
    setLoading(true);
    const { data, error } = await supabase
      .from("requisicoes")
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      .select("id, nome, loja_solicitante, loja_preparadora, data_pedido, data_recebimento, status, chegada_iniciada_at, chegada_concluida_at" as any)
      .ilike("loja_solicitante", `%${lojaNome}%`)
      .is("chegada_concluida_at", null)
      .order("data_recebimento", { ascending: true })
      .limit(50);
    if (error) {
      setLoading(false);
      return;
    }
    setReqs((data || []) as unknown as ReqChegada[]);
    setLoading(false);
  };

  useEffect(() => {
    if (lojaNome) loadReqs();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [lojaNome]);

  const openModal = async (req: ReqChegada) => {
    // Carrega itens + resolve produto_master_id por nome
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const { data: rawItens } = await (supabase
      .from("requisicoes_itens") as any)
      .select("id, nome_produto, quantidade_solicitada, quantidade_enviada, quantidade_recebida, recebida_via, recebida_at, ordem")
      .eq("requisicao_id", req.id)
      .order("ordem", { ascending: true });

    const itens = (rawItens || []) as Array<{
      id: number;
      nome_produto: string;
      quantidade_solicitada: number;
      quantidade_enviada: string | null;
      quantidade_recebida: string | null;
      recebida_via: "bip" | "manual" | null;
      recebida_at: string | null;
    }>;

    const nomesUnicos = Array.from(new Set(itens.map((i) => i.nome_produto)));
    const { data: produtos } = await supabase
      .from("produtos_master")
      .select("id, nome")
      .in("nome", nomesUnicos);

    const map = new Map<string, number>();
    ((produtos || []) as ProdutoNomeMap[]).forEach((p) => map.set(p.nome.toLowerCase().trim(), p.id));

    const chegadaItems: ChegadaItem[] = itens.map((it) => ({
      id: it.id,
      nome_produto: it.nome_produto,
      masterId: map.get(it.nome_produto.toLowerCase().trim()) ?? null,
      quantidade_solicitada: Number(it.quantidade_solicitada || 0),
      quantidade_enviada: String(it.quantidade_enviada || ""),
      quantidade_recebida: String(it.quantidade_recebida || ""),
      recebida_via: it.recebida_via,
      recebida_at: it.recebida_at,
    }));

    setModalItems(chegadaItems);
    setModalReq(req);
    setModalOpen(true);
  };

  const stats = useMemo(() => {
    const total = reqs.length;
    const iniciadas = reqs.filter((r) => r.chegada_iniciada_at).length;
    return { total, iniciadas };
  }, [reqs]);

  return (
    <div className="min-h-screen w-full bg-white dark:bg-[#0A0A0A] font-sans relative overflow-x-hidden transition-colors duration-300">
      {/* Faixa de toldo */}
      <div className="absolute top-0 left-0 right-0 h-1.5 bg-[repeating-linear-gradient(90deg,#57715B,#57715B_20px,#ffffff_20px,#ffffff_40px)] opacity-80 z-50 shadow-sm" />
      {/* Folhas decorativas */}
      <div className="fixed top-[-5%] right-[-10%] md:right-[-5%] w-[300px] md:w-[500px] h-[300px] md:h-[500px] opacity-[0.03] dark:opacity-[0.05] pointer-events-none animate-pulse" style={{ animationDuration: "10s" }}>
        <Leaf className="w-full h-full text-[#57715B] rotate-12" />
      </div>
      <div className="fixed bottom-[-10%] left-[-15%] md:left-[-5%] w-[400px] md:w-[600px] h-[400px] md:h-[600px] opacity-[0.03] dark:opacity-[0.05] pointer-events-none animate-pulse delay-1000" style={{ animationDuration: "12s" }}>
        <Leaf className="w-full h-full text-[#57715B] -rotate-45" />
      </div>
      {/* Brilhos ambientes */}
      <div className="fixed top-[20%] left-[10%] w-[200px] md:w-[400px] h-[200px] md:h-[400px] bg-[#57715B]/5 rounded-full blur-[80px] pointer-events-none" />
      <div className="fixed bottom-[30%] right-[10%] w-[250px] md:w-[500px] h-[250px] md:h-[500px] bg-[#C5A065]/5 rounded-full blur-[80px] pointer-events-none" />

      <div className="relative z-10 flex flex-col gap-4 sm:gap-6 px-4 sm:px-6 py-6 md:py-8 max-w-5xl mx-auto w-full">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-3 bg-white/50 dark:bg-zinc-900/50 p-4 sm:p-6 rounded-3xl border border-[#57715B]/10 backdrop-blur-md">
        <div className="flex items-center gap-3 sm:gap-4">
          <Button variant="ghost" size="sm" onClick={() => navigate(-1)} className="gap-2 min-h-[44px]">
            <ArrowLeft className="w-4 h-4" /> Voltar
          </Button>
          <div className="h-12 w-12 rounded-2xl bg-[#57715B]/10 flex items-center justify-center">
            <Truck className="h-6 w-6 text-[#57715B]" />
          </div>
          <div>
            <h1 className="text-xl sm:text-2xl font-bold text-[#57715B] dark:text-[#E6DCCF]">Conferência de Chegada</h1>
            <p className="text-xs sm:text-sm text-muted-foreground flex items-center gap-1">
              <MapPin className="w-3 h-3" /> {lojaNome || "Selecione uma loja"} · {stats.total} pendente(s)
            </p>
          </div>
        </div>
      </div>

      {!lojaId && (
        <Card className="border-amber-300 bg-amber-50/50">
          <CardContent className="p-4 flex items-center gap-3 text-amber-800">
            <AlertTriangle className="w-5 h-5" />
            <p className="text-sm">Selecione uma loja no menu superior pra ver as chegadas pendentes.</p>
          </CardContent>
        </Card>
      )}

      {loading && lojaId && (
        <div className="space-y-2">
          <Skeleton className="h-32 w-full" />
          <Skeleton className="h-32 w-full" />
        </div>
      )}

      {!loading && lojaId && reqs.length === 0 && (
        <Card className="border-[#57715B]/20 bg-white/60 dark:bg-black/20 backdrop-blur-md rounded-3xl">
          <CardContent className="p-8 text-center text-muted-foreground">
            <CheckCircle2 className="w-10 h-10 mx-auto mb-2 opacity-40 text-emerald-500" />
            <p className="text-sm font-semibold">Sem chegadas pendentes</p>
            <p className="text-xs mt-1">Quando uma requisição da {lojaNome} estiver a caminho, ela aparece aqui.</p>
          </CardContent>
        </Card>
      )}

-- =========================================================================
-- Etiquetas QR — fundação de rastreabilidade fim-a-fim por UID
-- Cada etiqueta impressa = 1 linha. UID gerado no front é a PK.
-- Mesma UID viaja em geração → separação → conferência → trânsito → recebimento.
-- =========================================================================

-- 1. Tabela master: 1 linha por etiqueta física
CREATE TABLE IF NOT EXISTS public.etiquetas_qr (
  uid                       text PRIMARY KEY,

  produto_master_id         integer NOT NULL REFERENCES public.produtos_master(id) ON DELETE RESTRICT,
  lote_id                   uuid NULL REFERENCES public.lotes(id) ON DELETE SET NULL,
  embalagem_nome            text NULL,
  quantidade_interna        numeric(12,3) NOT NULL DEFAULT 1,

  -- Snapshots (etiqueta histórica permanece legível mesmo se cadastro mudar)
  produto_nome_snapshot     text NULL,
  lote_codigo_snapshot      text NULL,
  lote_validade_snapshot    date NULL,

  -- Localização
  loja_origem_id            integer NULL REFERENCES public.lojas(id) ON DELETE SET NULL,
  loja_atual_id             integer NULL REFERENCES public.lojas(id) ON DELETE SET NULL,

  -- Status fim-a-fim
  status                    text NOT NULL DEFAULT 'gerada'
                            CHECK (status IN (
                              'gerada','em_separacao','separada',
                              'conferida','em_transito','recebida',
                              'consumida','descartada'
                            )),

  -- Origem
  gerada_por                uuid NULL REFERENCES auth.users(id) ON DELETE SET NULL,
  gerada_at                 timestamptz NULL,
  ultima_movimentacao_id    integer NULL REFERENCES public.movimentacoes(id) ON DELETE SET NULL,

  -- Reposição (nova etiqueta substitui antiga perdida/danificada)
  replaces_uid              text NULL REFERENCES public.etiquetas_qr(uid) ON DELETE SET NULL,
  replaced_by_uid           text NULL REFERENCES public.etiquetas_qr(uid) ON DELETE SET NULL,

  -- Backfill (etiqueta antiga registrada retroativamente ao bipar)
  backfilled                boolean NOT NULL DEFAULT false,

  -- Snapshot do payload original (anti-tamper / forensics)
  qr_payload                jsonb NULL,

  created_at                timestamptz NOT NULL DEFAULT now(),
  updated_at                timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_etiquetas_qr_produto      ON public.etiquetas_qr(produto_master_id);
CREATE INDEX IF NOT EXISTS idx_etiquetas_qr_lote         ON public.etiquetas_qr(lote_id);
CREATE INDEX IF NOT EXISTS idx_etiquetas_qr_loja_atual   ON public.etiquetas_qr(loja_atual_id);
CREATE INDEX IF NOT EXISTS idx_etiquetas_qr_status       ON public.etiquetas_qr(status);
CREATE INDEX IF NOT EXISTS idx_etiquetas_qr_gerada_at    ON public.etiquetas_qr(gerada_at DESC NULLS LAST);

COMMENT ON TABLE public.etiquetas_qr IS
  'Source of truth de etiquetas QR físicas. Cada UID = 1 caixa rastreada fim-a-fim (geração → separação → conferência → trânsito → recebimento).';


-- 2. Tabela append-only de eventos (timeline)
CREATE TABLE IF NOT EXISTS public.etiquetas_qr_eventos (
  id                bigserial PRIMARY KEY,
  etiqueta_uid      text NOT NULL REFERENCES public.etiquetas_qr(uid) ON DELETE CASCADE,
  tipo_evento       text NOT NULL,
  etapa             text NOT NULL CHECK (etapa IN (
                       'geracao','separacao','conferencia',
                       'entrada','saida','consumo',
                       'descarte','reposicao','backfill'
                    )),
  status_anterior   text NULL,
  status_novo       text NULL,
  loja_id           integer NULL REFERENCES public.lojas(id) ON DELETE SET NULL,
  usuario_id        uuid NULL REFERENCES auth.users(id) ON DELETE SET NULL,
  usuario_nome      text NULL,
  referencia_tipo   text NULL,
  referencia_id     text NULL,
  metadata          jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at        timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_etiquetas_eventos_uid_at  ON public.etiquetas_qr_eventos(etiqueta_uid, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_etiquetas_eventos_etapa   ON public.etiquetas_qr_eventos(etapa, created_at DESC);

COMMENT ON TABLE public.etiquetas_qr_eventos IS
  'Timeline append-only de bips e transições de status por etiqueta. Nunca atualizar nem deletar (audit).';


-- 3. Trigger updated_at
CREATE OR REPLACE FUNCTION public.tg_etiquetas_qr_set_updated_at()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_etiquetas_qr_updated_at ON public.etiquetas_qr;
CREATE TRIGGER trg_etiquetas_qr_updated_at
BEFORE UPDATE ON public.etiquetas_qr
FOR EACH ROW EXECUTE FUNCTION public.tg_etiquetas_qr_set_updated_at();


-- 4. Trigger: ao inserir etiqueta (não-backfill), registrar evento 'geracao'
CREATE OR REPLACE FUNCTION public.tg_etiquetas_qr_log_geracao()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF NEW.backfilled = false THEN
    INSERT INTO public.etiquetas_qr_eventos (
      etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
      loja_id, usuario_id, metadata
    ) VALUES (
      NEW.uid, 'gerada', 'geracao', NULL, NEW.status,
      NEW.loja_origem_id, NEW.gerada_por, COALESCE(NEW.qr_payload, '{}'::jsonb)
    );
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_etiquetas_qr_log_geracao ON public.etiquetas_qr;
CREATE TRIGGER trg_etiquetas_qr_log_geracao
AFTER INSERT ON public.etiquetas_qr
FOR EACH ROW EXECUTE FUNCTION public.tg_etiquetas_qr_log_geracao();


-- 5. RPC bipar_etiqueta — single source of truth de validação + transição
CREATE OR REPLACE FUNCTION public.bipar_etiqueta(
  p_uid       text,
  p_etapa     text,
  p_contexto  jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_etiqueta            public.etiquetas_qr%ROWTYPE;
  v_user_id             uuid := auth.uid();
  v_user_nome           text;
  v_status_anterior     text;
  v_status_novo         text;
  v_loja_id             integer;
  v_alertas             jsonb := '[]'::jsonb;
  v_referencia_tipo     text;
  v_referencia_id       text;
  v_payload             jsonb;
BEGIN
  -- Etapas válidas
  IF p_etapa NOT IN ('separacao','conferencia','entrada','saida','consumo','descarte') THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Etapa inválida: ' || p_etapa);
  END IF;

  -- Nome do usuário (denormalizado p/ timeline ler sem JOIN)
  SELECT COALESCE(raw_user_meta_data->>'nome', email)
    INTO v_user_nome
    FROM auth.users WHERE id = v_user_id;

  v_loja_id         := NULLIF(p_contexto->>'loja_id','')::integer;
  v_referencia_tipo := p_contexto->>'referencia_tipo';
  v_referencia_id   := p_contexto->>'referencia_id';
  v_payload         := p_contexto->'payload';

  -- Lookup
  SELECT * INTO v_etiqueta FROM public.etiquetas_qr WHERE uid = p_uid;

  -- ===== BACKFILL =====
  -- Etiqueta inexistente + payload presente → registra retroativamente
  IF NOT FOUND THEN
    IF v_payload IS NULL OR (v_payload->>'p') IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta não cadastrada e sem payload para backfill');
    END IF;

    INSERT INTO public.etiquetas_qr (
      uid, produto_master_id, lote_id, embalagem_nome, quantidade_interna,
      loja_origem_id, loja_atual_id, status, backfilled, qr_payload
    ) VALUES (
      p_uid,
      (v_payload->>'p')::integer,
      NULLIF(v_payload->>'l','')::uuid,
      v_payload->>'n',
      COALESCE(NULLIF(v_payload->>'q','')::numeric, 1),
      NULL, v_loja_id,
      CASE p_etapa
        WHEN 'separacao'   THEN 'separada'
        WHEN 'conferencia' THEN 'conferida'
        WHEN 'entrada'     THEN 'recebida'
        WHEN 'saida'       THEN 'em_transito'
        WHEN 'consumo'     THEN 'consumida'
        WHEN 'descarte'    THEN 'descartada'
      END,
      true,
      v_payload
    )
    RETURNING * INTO v_etiqueta;

    v_alertas := v_alertas || jsonb_build_array('Etiqueta antiga registrada retroativamente (backfill)');

    INSERT INTO public.etiquetas_qr_eventos (
      etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
      loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata
    ) VALUES (
      p_uid, 'backfilled', 'backfill', NULL, v_etiqueta.status,
      v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id,
      jsonb_build_object('etapa_origem', p_etapa, 'payload', v_payload)
    );

    RETURN jsonb_build_object(
      'ok', true,
      'etiqueta', to_jsonb(v_etiqueta),
      'status_anterior', NULL,
      'status_novo', v_etiqueta.status,
      'alertas', v_alertas,
      'backfilled', true
    );
  END IF;

  -- ===== Etiqueta encontrada — validar transição =====
  v_status_anterior := v_etiqueta.status;

  IF v_etiqueta.status = 'descartada' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'erro', 'Etiqueta descartada' ||
              CASE WHEN v_etiqueta.replaced_by_uid IS NOT NULL
                   THEN ' (substituída por ' || v_etiqueta.replaced_by_uid || ')'
                   ELSE ''
              END,
      'etiqueta', to_jsonb(v_etiqueta)
    );
  END IF;

  -- Mapa de transições válidas. NULL = transição inválida (duplicata ou fora de ordem)
  v_status_novo := CASE p_etapa
    WHEN 'separacao' THEN
      CASE WHEN v_etiqueta.status IN ('gerada','recebida','em_separacao') THEN 'separada'
           ELSE NULL END
    WHEN 'conferencia' THEN
      CASE WHEN v_etiqueta.status IN ('separada','gerada','recebida') THEN 'conferida'
           ELSE NULL END
    WHEN 'saida' THEN
      CASE WHEN v_etiqueta.status IN ('conferida','separada','gerada') THEN 'em_transito'
           ELSE NULL END
    WHEN 'entrada' THEN
      CASE WHEN v_etiqueta.status IN ('em_transito','gerada','conferida') THEN 'recebida'
           WHEN v_etiqueta.status = 'recebida' AND v_loja_id IS DISTINCT FROM v_etiqueta.loja_atual_id THEN 'recebida'
           ELSE NULL END
    WHEN 'consumo'   THEN 'consumida'

