                <Badge variant="outline" className="bg-amber-100 text-amber-800 border-amber-300">
                  Em conferência
                </Badge>
              )}
            </div>
          </CardHeader>
          <CardContent className="grid grid-cols-1 sm:grid-cols-3 gap-2 text-xs">
            <Field icon={MapPin} label="Origem">{req.loja_preparadora}</Field>
            <Field icon={Calendar} label="Pedido">{fmtDate(req.data_pedido)}</Field>
            <Field icon={Calendar} label="Recebimento">{fmtDate(req.data_recebimento)}</Field>
          </CardContent>
        </Card>
      ))}

      {modalReq && lojaId && (
        <RequisicaoChegadaModal
          isOpen={modalOpen}
          onClose={() => {
            setModalOpen(false);
            loadReqs();
          }}
          requisicaoId={modalReq.id}
          requisicaoNome={modalReq.nome}
          lojaDestinoId={lojaId}
          lojaDestinoNome={lojaNome}
          items={modalItems}
          onConcluida={loadReqs}
        />
      )}
      </div>
    </div>
  );
}

function Field({ icon: Icon, label, children }: { icon: React.ElementType; label: string; children: React.ReactNode }) {
  return (
    <div className="space-y-0.5">
      <p className="text-[10px] uppercase tracking-wider text-muted-foreground font-bold flex items-center gap-1">
        <Icon className="w-3 h-3" /> {label}
      </p>
      <p className="text-sm font-semibold">{children}</p>
    </div>
  );
}
